insert into public.sq_en_content(id,base_id,owner_id,level,ordinal,status,revision,payload) values('en-b2-02','en-b2-02',null,4,2,'published',1,'{"id":"en-b2-02","baseId":"en-b2-02","revision":1,"level":"B2","levelIndex":4,"order":2,"title":"Future Continuous va Future Perfect","objective":"Kelajakdagi davom etadigan ishni o‘sha paytgacha tugaydigan natijadan ajratasiz.","context":"Maktab ko‘rgazmasi uchun muddatlar.","prerequisites":["en-b2-01"],"minutes":55,"skills":["grammar","vocabulary","pronunciation","listening","reading","writing","speaking"],"rules":["Will be + -ing kelajakdagi bir vaqtda davom etayotgan ishni ko‘rsatadi.","Will have + V3 kelajak nuqtasigacha tugallangan natijani bildiradi.","By Friday — juma kelguncha; at ten — o‘n paytida. Muddat real reja bilan mos bo‘lsin."],"pattern":"at ten: will be preparing / by ten: will have prepared","examples":["At ten we will be arranging the displays.","By noon we will have finished the labels.","Will you be using the projector?","The guests will be arriving at two.","We will have checked the cables by then.","The team will not have finished by nine."],"vocabulary":[{"id":"en-b2-02-v0","term":"deadline","meaning":"yakuniy muddat","ipa":"/ˈdedlaɪn/","collocation":"meet a deadline","example":"The organiser asks everyone to state both their activity and the result promised by a deadline."},{"id":"en-b2-02-v1","term":"schedule","meaning":"jadval","ipa":"/ˈʃedjuːl/","collocation":"a realistic schedule","example":"The new schedule avoids that confusion."},{"id":"en-b2-02-v2","term":"display","meaning":"ko‘rgazma","ipa":"/dɪˈspleɪ/","collocation":"arrange a display","example":"At ten we will be arranging the displays."},{"id":"en-b2-02-v3","term":"by then","meaning":"o‘sha paytgacha","ipa":"/baɪ ðen/","collocation":"completed by then","example":"We will have checked the cables by then."}],"visuals":[{"kind":"timeline","title":"Ma’no va tuzilish","items":["at ten: will be preparing / by ten: will have prepared","At ten we will be arranging the displays.","By noon we will have finished the labels."],"timeline":[{"why":"Will be arranging kelajakdagi soat o‘nda davom etayotgan jarayonni ko‘rsatadi.","events":[{"kind":"span","from":425,"to":505,"label":"Kelajakdagi jarayon"},{"kind":"point","x":465,"label":"Soat o‘n"}]},{"why":"Will have finished kelajakdagi tush paytigacha tugagan natijani ko‘rsatadi.","events":[{"kind":"point","x":490,"label":"Ish tugashi"},{"kind":"point","x":565,"label":"Tush paytidagi chegara"}]}]},{"kind":"argument","title":"Fikr va dalilning aloqasi","items":["The schedule separates activity and completion.","Labels finish by noon; cables need another thirty minutes.","The room deadline is later than the label deadline."]}],"pronunciation":{"focus":"Gapdagi mazmunli so‘zlarni urg‘u bilan ayting. Nuqtada to‘xtab, yozuvni qayta tinglang.","text":"The guests will be arriving at two.","audio":"/english-course/v7.23/en-b2-02-dictation.mp3"},"exercises":[{"id":"en-b2-02-choice","type":"choice","skill":"grammar","prompt":"Til vositasini tanlang: At ten we will be ___ displays. (arrange)","answers":["arranging"],"explanation":"Will be + -ing kelajakdagi bir vaqtda davom etayotgan ishni ko‘rsatadi. Will have + V3 kelajak nuqtasigacha tugallangan natijani bildiradi. By Friday — juma kelguncha; at ten — o‘n paytida. Muddat real reja bilan mos bo‘lsin.","hint":"at ten: will be preparing / by ten: will have prepared","options":["arranging","arranged","arrange"]},{"id":"en-b2-02-gap","type":"grammarFill","skill":"grammar","prompt":"At ten we will be ___ displays. (arrange)","answers":["arranging"],"explanation":"Will be + -ing kelajakdagi bir vaqtda davom etayotgan ishni ko‘rsatadi. Will have + V3 kelajak nuqtasigacha tugallangan natijani bildiradi. By Friday — juma kelguncha; at ten — o‘n paytida. Muddat real reja bilan mos bo‘lsin.","hint":"at ten: will be preparing / by ten: will have prepared"},{"id":"en-b2-02-order","type":"order","skill":"grammar","prompt":"Kartalarni to‘g‘ri tartibga qo‘ying.","answers":["At ten we will be arranging the displays."],"explanation":"Will be + -ing kelajakdagi bir vaqtda davom etayotgan ishni ko‘rsatadi. Will have + V3 kelajak nuqtasigacha tugallangan natijani bildiradi. By Friday — juma kelguncha; at ten — o‘n paytida. Muddat real reja bilan mos bo‘lsin.","hint":"at ten: will be preparing / by ten: will have prepared","tokens":["At","ten","we","will","be","arranging","the","displays."]},{"id":"en-b2-02-fix","type":"correction","skill":"grammar","prompt":"By noon we will have finish the labels.","answers":["By noon we will have finished the labels."],"explanation":"Will be + -ing kelajakdagi bir vaqtda davom etayotgan ishni ko‘rsatadi. Will have + V3 kelajak nuqtasigacha tugallangan natijani bildiradi. By Friday — juma kelguncha; at ten — o‘n paytida. Muddat real reja bilan mos bo‘lsin.","hint":"at ten: will be preparing / by ten: will have prepared"},{"id":"en-b2-02-vocabulary","type":"matching","skill":"vocabulary","prompt":"So‘zlarni ma’nolari bilan moslang.","answers":["yakuniy muddat","jadval","ko‘rgazma","o‘sha paytgacha"],"explanation":"So‘zni alohida emas, darsdagi birikma va gap bilan eslang.","hint":"at ten: will be preparing / by ten: will have prepared","left":["deadline","schedule","display","by then"],"options":["yakuniy muddat","jadval","ko‘rgazma","o‘sha paytgacha"]},{"id":"en-b2-02-transform","type":"transformation","skill":"grammar","prompt":"By noon tugallanish: We plan to finish the labels before noon.","answers":["We will have finished the labels by noon."],"hint":"at ten: will be preparing / by ten: will have prepared","explanation":"Will be + -ing kelajakdagi bir vaqtda davom etayotgan ishni ko‘rsatadi."},{"id":"en-b2-02-paragraphs","type":"paragraphOrder","skill":"reading","prompt":"Fikrni tartiblang: da’vo → dalil → talqin.","tokens":["The schedule separates activity and completion.","Labels finish by noon; cables need another thirty minutes.","The room deadline is later than the label deadline."],"answers":["The schedule separates activity and completion.\nLabels finish by noon; cables need another thirty minutes.\nThe room deadline is later than the label deadline."],"hint":"Da’vo nimani aytadi? Dalil nimani ko‘rsatadi?","explanation":"Dalil yakuniy xulosaning o‘rnini bosmaydi; talqin ularning aloqasini tushuntiradi."}],"reading":{"title":"Asosiy matn va muallif pozitsiyasi","text":"The exhibition opens at two, but preparation continues through the morning. At ten, one group will be arranging the displays while another checks the projector. By noon, they will have finished the labels. This does not mean that the whole room will be ready at noon: cables still need checking. The organiser asks everyone to state both their activity and the result promised by a deadline. Last year, a team said it would be working on the posters at eleven. Other groups mistakenly understood this as a promise that the posters would be finished by eleven. The new schedule avoids that confusion. It also includes a buffer before visitors arrive. A timetable is useful only when people agree on what each time refers to and what evidence will show that a task is complete.","sentences":["The exhibition opens at two, but preparation continues through the morning.","At ten, one group will be arranging the displays while another checks the projector.","By noon, they will have finished the labels.","This does not mean that the whole room will be ready at noon: cables still need checking.","The organiser asks everyone to state both their activity and the result promised by a deadline.","Last year, a team said it would be working on the posters at eleven.","Other groups mistakenly understood this as a promise that the posters would be finished by eleven.","The new schedule avoids that confusion.","It also includes a buffer before visitors arrive.","A timetable is useful only when people agree on what each time refers to and what evidence will show that a task is complete."],"questions":[{"id":"en-b2-02-reading0","type":"choice","skill":"reading","prompt":"Nega yangi jadval ikki narsani ajratadi?","answers":["activity time and completion deadline were confused"],"explanation":"Davom va yakun vaqtini chalkashtirishgan.","hint":"at ten: will be preparing / by ten: will have prepared","options":["activity time and completion deadline were confused","visitors arrive at noon","labels need no work"]},{"id":"en-b2-02-reading1","type":"choice","skill":"reading","prompt":"Noonda xona tayyormi?","answers":["not necessarily"],"explanation":"Labels tugashi barcha vazifa tugashi emas.","hint":"at ten: will be preparing / by ten: will have prepared","options":["not necessarily","definitely","never"]},{"id":"en-b2-02-evidence","type":"evidence","skill":"reading","prompt":"Vaziyatni tanishtiradigan birinchi jumlani tanlang.","answers":["0"],"explanation":"Birinchi jumla matn vaziyatini tanishtiradi; keyingi jumlalar uni rivojlantiradi.","hint":"at ten: will be preparing / by ten: will have prepared","options":["The exhibition opens at two, but preparation continues through the morning.","At ten, one group will be arranging the displays while another checks the projector.","By noon, they will have finished the labels.","This does not mean that the whole room will be ready at noon: cables still need checking.","The organiser asks everyone to state both their activity and the result promised by a deadline.","Last year, a team said it would be working on the posters at eleven.","Other groups mistakenly understood this as a promise that the posters would be finished by eleven.","The new schedule avoids that confusion.","It also includes a buffer before visitors arrive.","A timetable is useful only when people agree on what each time refers to and what evidence will show that a task is complete."]}]},"listening":{"title":"Boshqa nuqtayi nazarni tinglang","transcript":"At ten we will be arranging the displays. By noon we will have finished the labels, but we still need thirty minutes to check the cables. Visitors arrive at two. Please do not treat the label deadline as the completion time for the whole room.","audio":"/english-course/v7.23/en-b2-02.mp3","synthetic":true,"questions":[{"id":"en-b2-02-listening0","type":"choice","skill":"listening","prompt":"Cables uchun vaqt?","answers":["thirty minutes"],"explanation":"Thirty minutes.","hint":"at ten: will be preparing / by ten: will have prepared","options":["thirty minutes","two hours","ten minutes"]},{"id":"en-b2-02-listening1","type":"choice","skill":"listening","prompt":"Mehmonlar qachon?","answers":["two"],"explanation":"Arrive at two.","hint":"at ten: will be preparing / by ten: will have prepared","options":["two","noon","ten"]},{"id":"en-b2-02-audio-table","type":"table","skill":"listening","prompt":"Tinglangan ma’lumotni jadvalga yozing.","answers":["noon","thirty minutes"],"explanation":"Jadvaldagi javoblar yozuvda aynan aytilgan. Mavjud bo‘lmagan tafsilotni taxmin qilmang.","hint":"at ten: will be preparing / by ten: will have prepared","rows":["Labels muddati","Cable tekshiruvi"]},{"id":"en-b2-02-dictation","type":"dictation","skill":"listening","prompt":"Eshitgan gapingizni yozing.","answers":["The guests will be arriving at two."],"explanation":"Gapdagi asosiy so‘zlar, yordamchi fe’l va inkor saqlanishi kerak.","hint":"at ten: will be preparing / by ten: will have prepared","audio":"/english-course/v7.23/en-b2-02-dictation.mp3","transcript":"The guests will be arriving at two."}]},"writing":{"task":"Ko‘rgazma uchun davom etuvchi vazifa va yakuniy muddatlari ajratilgan email yozing.","audience":"Maktab kengashi yoki loyiha guruhi","minWords":90,"maxWords":320,"plan":["Da’vo va maqsadni aniqlang.","Reading va listeningdan bir dalilni qiyoslang.","Cheklov yoki qarshi fikrni tushuntiring.","Auditoriyaga mos amaliy xulosa yozing."],"model":"Dear team, at ten we will be arranging the displays and testing the projector. By noon, we will have finished the labels. However, the room will not be fully ready until the cables have been checked. We have allowed thirty minutes for that task and a further buffer before visitors arrive at two. Please distinguish an activity in progress from a result promised by a deadline. If your group expects a delay, tell us which result will be affected rather than simply saying that you will still be busy. This will allow the other groups to adjust their plans without misunderstanding the schedule.","modelNotes":["Kirishda auditoriya va maqsad aniq.","Asosiy qism dalilni talqin bilan bog‘laydi.","Yakun haddan tashqari umumlashtirmaydi."],"phrases":["At ten we will be arranging the displays.","By noon we will have finished the labels.","Will you be using the projector?"],"checklist":["Topshiriq va auditoriyaga mos yozdim.","Fikrni o‘z so‘zlarim bilan ifodaladim.","Darsdagi shaklni to‘g‘ri ishlatdim.","Imlo, bog‘lanish va tinish belgilarini tekshirdim."]},"speaking":{"task":"Ikki guruhning vaqt jadvalini kelishtiring; by va at farqini aniqlashtiring.","seconds":100,"prompts":["Reading va listening qayerda mos, qayerda farqli?","Sherigingizning e’tiroziga javob bering.","Qaysi dalil xulosangizni o‘zgartirishi mumkin?"],"rubric":["Vazifani bajarish","Til vositalari va aniqlik","Bog‘langan, tushunarli nutq","Talaffuz va muloqot"]},"rubrics":{"writing":["Mazmun va vazifani bajarish","Tuzilish va bog‘lanish","Til vositalari va uslub","Grammatika va imlo"],"speaking":["Vazifa va o‘zaro muloqot","Ravonlik va bog‘lanish","Til vositalari va aniqlik","Tushunarlilik va talaffuz"]},"realTask":"Ko‘rgazma uchun davom etuvchi vazifa va yakuniy muddatlari ajratilgan email yozing.","exit":[[{"id":"en-b2-02-exit0","type":"grammarFill","skill":"grammar","prompt":"At ten we will be ___ displays. (arrange)","answers":["arranging"],"explanation":"Will be + -ing kelajakdagi bir vaqtda davom etayotgan ishni ko‘rsatadi. Will have + V3 kelajak nuqtasigacha tugallangan natijani bildiradi. By Friday — juma kelguncha; at ten — o‘n paytida. Muddat real reja bilan mos bo‘lsin.","hint":"at ten: will be preparing / by ten: will have prepared"},{"id":"en-b2-02-exit1","type":"grammarFill","skill":"grammar","prompt":"By noon we will have ___ labels. (finish)","answers":["finished"],"explanation":"Will be + -ing kelajakdagi bir vaqtda davom etayotgan ishni ko‘rsatadi. Will have + V3 kelajak nuqtasigacha tugallangan natijani bildiradi. By Friday — juma kelguncha; at ten — o‘n paytida. Muddat real reja bilan mos bo‘lsin.","hint":"at ten: will be preparing / by ten: will have prepared"},{"id":"en-b2-02-exit2","type":"grammarFill","skill":"grammar","prompt":"Will you be ___ the projector? (use)","answers":["using"],"explanation":"Will be + -ing kelajakdagi bir vaqtda davom etayotgan ishni ko‘rsatadi. Will have + V3 kelajak nuqtasigacha tugallangan natijani bildiradi. By Friday — juma kelguncha; at ten — o‘n paytida. Muddat real reja bilan mos bo‘lsin.","hint":"at ten: will be preparing / by ten: will have prepared"},{"id":"en-b2-02-exit3","type":"choice","skill":"grammar","prompt":"Noongacha tugashni bildiruvchi gap?","answers":["We will have finished by noon."],"explanation":"Future Perfect tugallanish.","hint":"at ten: will be preparing / by ten: will have prepared","options":["We will have finished by noon.","We will be working at noon.","We worked at noon."]},{"id":"en-b2-02-exit4","type":"choice","skill":"grammar","prompt":"Noonda xona tayyormi?","answers":["not necessarily"],"explanation":"Labels tugashi barcha vazifa tugashi emas.","hint":"at ten: will be preparing / by ten: will have prepared","options":["not necessarily","definitely","never"]}],[{"id":"en-b2-02-exit-b0","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["By noon we will have finished the labels."],"explanation":"Will be + -ing kelajakdagi bir vaqtda davom etayotgan ishni ko‘rsatadi. Will have + V3 kelajak nuqtasigacha tugallangan natijani bildiradi. By Friday — juma kelguncha; at ten — o‘n paytida. Muddat real reja bilan mos bo‘lsin.","hint":"at ten: will be preparing / by ten: will have prepared","tokens":["By","noon","we","will","have","finished","the","labels."]},{"id":"en-b2-02-exit-b1","type":"grammarFill","skill":"grammar","prompt":"By noon we will have ___ labels. (finish)","answers":["finished"],"explanation":"Will be + -ing kelajakdagi bir vaqtda davom etayotgan ishni ko‘rsatadi. Will have + V3 kelajak nuqtasigacha tugallangan natijani bildiradi. By Friday — juma kelguncha; at ten — o‘n paytida. Muddat real reja bilan mos bo‘lsin.","hint":"at ten: will be preparing / by ten: will have prepared"},{"id":"en-b2-02-exit-b2","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["The guests will be arriving at two."],"explanation":"Will be + -ing kelajakdagi bir vaqtda davom etayotgan ishni ko‘rsatadi. Will have + V3 kelajak nuqtasigacha tugallangan natijani bildiradi. By Friday — juma kelguncha; at ten — o‘n paytida. Muddat real reja bilan mos bo‘lsin.","hint":"at ten: will be preparing / by ten: will have prepared","tokens":["The","guests","will","be","arriving","at","two."]},{"id":"en-b2-02-exit-b3","type":"choice","skill":"grammar","prompt":"Noongacha tugashni bildiruvchi gap?","answers":["We will have finished by noon."],"explanation":"Future Perfect tugallanish.","hint":"at ten: will be preparing / by ten: will have prepared","options":["We will have finished by noon.","We will be working at noon.","We worked at noon."]},{"id":"en-b2-02-exit-b4","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["The team will not have finished by nine."],"explanation":"Will be + -ing kelajakdagi bir vaqtda davom etayotgan ishni ko‘rsatadi. Will have + V3 kelajak nuqtasigacha tugallangan natijani bildiradi. By Friday — juma kelguncha; at ten — o‘n paytida. Muddat real reja bilan mos bo‘lsin.","hint":"at ten: will be preparing / by ten: will have prepared","tokens":["The","team","will","not","have","finished","by","nine."]}]],"sources":[{"id":"cefr","name":"Council of Europe — CEFR daraja tavsiflari","levels":["PRE","A1","A2","B1","B2","C1"],"skill":"framework","url":"https://www.coe.int/en/web/common-european-framework-reference-languages/level-descriptions","task":"Dars maqsadini qila olaman tavsifi bilan solishtiring. PRE — kursning tayyorlov bosqichi.","lesson":"en-b2-02","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"pronunciation","name":"Cambridge Dictionary — Pronunciation","levels":["PRE","A1","A2","B1","B2","C1"],"skill":"pronunciation","url":"https://dictionary.cambridge.org/pronunciation/","task":"Darsdan ikki so‘z tanlang, UK/US talaffuzini eshiting va urg‘uni qayd eting.","lesson":"en-b2-02","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-grammar","name":"British Council — Grammar","levels":["A1","A2","B1","B2","C1"],"skill":"grammar","url":"https://learnenglish.britishcouncil.org/free-resources/grammar","task":"Darajangizdagi dars mavzusini toping va bitta o‘xshash misol yozing.","lesson":"en-b2-02","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-read","name":"British Council — Reading","levels":["A1","A2","B1","B2","C1"],"skill":"reading","url":"https://learnenglish.britishcouncil.org/free-resources/reading","task":"O‘z darajangizdagi matnni tanlang; asosiy fikr va bitta dalilni ajrating.","lesson":"en-b2-02","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-write","name":"British Council — Writing","levels":["A1","A2","B1","B2","C1"],"skill":"writing","url":"https://learnenglish.britishcouncil.org/free-resources/writing","task":"Darajangizdagi namunaning kirish, asosiy qism va yakunini tahlil qiling.","lesson":"en-b2-02","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-speak","name":"British Council — Speaking (A1–B2)","levels":["A1","A2","B1","B2"],"skill":"speaking","url":"https://learnenglish.britishcouncil.org/free-resources/speaking","task":"Darajangizdagi video vaziyatidan ikki iborani o‘z dialogingizda ishlating.","lesson":"en-b2-02","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-listen","name":"British Council — Listening (A1–C1)","levels":["A1","A2","B1","B2","C1"],"skill":"listening","url":"https://learnenglish.britishcouncil.org/free-resources/listening","task":"Mos daraja audiosini transkriptsiz tinglang; keyin yozuv bilan tekshiring.","lesson":"en-b2-02","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"cambridge","name":"Cambridge English — Activities","levels":["A1","A2","B1","B2","C1"],"skill":"integrated","url":"https://www.cambridgeenglish.org/learning-english/activities-for-learners/","task":"A1–A2, B1–B2 yoki C1–C2 filtrini qo‘llang; dars ko‘nikmasiga mos mashqni tanlang.","lesson":"en-b2-02","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."}],"recapEvery":4,"project":false,"rights":"Original SinfQuiz content; local Flite synthetic speech. Educational references are linked, not copied."}'::jsonb) on conflict(id,revision) do nothing;
insert into public.sq_en_content(id,base_id,owner_id,level,ordinal,status,revision,payload) values('en-b2-03','en-b2-03',null,4,3,'published',1,'{"id":"en-b2-03","baseId":"en-b2-03","revision":1,"level":"B2","levelIndex":4,"order":3,"title":"Third Conditional: bo‘lmagan o‘tmish","objective":"O‘tmishdagi tanlovning muqobil natijasini dalildan ajratib aytasiz.","context":"Sayohat rejasidan saboq olish.","prerequisites":["en-b2-02"],"minutes":55,"skills":["grammar","vocabulary","pronunciation","listening","reading","writing","speaking"],"rules":["If + had + V3, would have + V3 sodir bo‘lmagan o‘tmishning taxminiy natijasi.","Would if qismida odatiy third conditional shakli emas.","Muqobil natija taxmin: haqiqiy tarix sifatida aytmang; could yoki might ehtimolni o‘zgartiradi."],"pattern":"If we had checked, we would have noticed.","examples":["If we had checked the timetable, we would have noticed the change.","We would have arrived earlier if we had left at eight.","If I had asked, she might have helped.","They could have waited if they had known.","Had we planned better, we would have saved time.","The trip would not have failed if the bus had arrived."],"vocabulary":[{"id":"en-b2-03-v0","term":"alternative","meaning":"muqobil","ipa":"/ɔːlˈtɜːnətɪv/","collocation":"an alternative outcome","example":"During the review, the group separates facts from imagined alternatives."},{"id":"en-b2-03-v1","term":"overlook","meaning":"e’tibordan qochirmoq","ipa":"/ˌəʊvəˈlʊk/","collocation":"overlook a change","example":"overlook a change"},{"id":"en-b2-03-v2","term":"regret","meaning":"afsus","ipa":"/rɪˈɡret/","collocation":"express regret","example":"express regret"},{"id":"en-b2-03-v3","term":"prevent","meaning":"oldini olmoq","ipa":"/prɪˈvent/","collocation":"prevent a delay","example":"We can reasonably say that checking might have prevented the first delay."}],"visuals":[{"kind":"argument","title":"Ma’no va tuzilish","items":["If we had checked, we would have noticed.","If we had checked the timetable, we would have noticed the change.","We would have arrived earlier if we had left at eight."]},{"kind":"argument","title":"Fikr va dalilning aloqasi","items":["The timetable caused the first delay.","Rain later closed the route.","One better decision would not have controlled every outcome."]}],"pronunciation":{"focus":"Gapdagi mazmunli so‘zlarni urg‘u bilan ayting. Nuqtada to‘xtab, yozuvni qayta tinglang.","text":"They could have waited if they had known.","audio":"/english-course/v7.23/en-b2-03-dictation.mp3"},"exercises":[{"id":"en-b2-03-choice","type":"choice","skill":"grammar","prompt":"Til vositasini tanlang: If we had ___, we would have noticed. (check)","answers":["checked"],"explanation":"If + had + V3, would have + V3 sodir bo‘lmagan o‘tmishning taxminiy natijasi. Would if qismida odatiy third conditional shakli emas. Muqobil natija taxmin: haqiqiy tarix sifatida aytmang; could yoki might ehtimolni o‘zgartiradi.","hint":"If we had checked, we would have noticed.","options":["checked","checking","check"]},{"id":"en-b2-03-gap","type":"grammarFill","skill":"grammar","prompt":"If we had ___, we would have noticed. (check)","answers":["checked"],"explanation":"If + had + V3, would have + V3 sodir bo‘lmagan o‘tmishning taxminiy natijasi. Would if qismida odatiy third conditional shakli emas. Muqobil natija taxmin: haqiqiy tarix sifatida aytmang; could yoki might ehtimolni o‘zgartiradi.","hint":"If we had checked, we would have noticed."},{"id":"en-b2-03-order","type":"order","skill":"grammar","prompt":"Kartalarni to‘g‘ri tartibga qo‘ying.","answers":["If we had checked the timetable, we would have noticed the change."],"explanation":"If + had + V3, would have + V3 sodir bo‘lmagan o‘tmishning taxminiy natijasi. Would if qismida odatiy third conditional shakli emas. Muqobil natija taxmin: haqiqiy tarix sifatida aytmang; could yoki might ehtimolni o‘zgartiradi.","hint":"If we had checked, we would have noticed.","tokens":["If","we","had","checked","the","timetable,","we","would","have","noticed","the","change."]},{"id":"en-b2-03-fix","type":"correction","skill":"grammar","prompt":"If we would have checked, we would have noticed.","answers":["If we had checked, we would have noticed."],"explanation":"If + had + V3, would have + V3 sodir bo‘lmagan o‘tmishning taxminiy natijasi. Would if qismida odatiy third conditional shakli emas. Muqobil natija taxmin: haqiqiy tarix sifatida aytmang; could yoki might ehtimolni o‘zgartiradi.","hint":"If we had checked, we would have noticed."},{"id":"en-b2-03-vocabulary","type":"matching","skill":"vocabulary","prompt":"So‘zlarni ma’nolari bilan moslang.","answers":["muqobil","e’tibordan qochirmoq","afsus","oldini olmoq"],"explanation":"So‘zni alohida emas, darsdagi birikma va gap bilan eslang.","hint":"If we had checked, we would have noticed.","left":["alternative","overlook","regret","prevent"],"options":["muqobil","e’tibordan qochirmoq","afsus","oldini olmoq"]},{"id":"en-b2-03-transform","type":"transformation","skill":"grammar","prompt":"Third conditional: We did not check, so we did not notice.","answers":["If we had checked, we would have noticed."],"hint":"If we had checked, we would have noticed.","explanation":"If + had + V3, would have + V3 sodir bo‘lmagan o‘tmishning taxminiy natijasi."},{"id":"en-b2-03-paragraphs","type":"paragraphOrder","skill":"reading","prompt":"Fikrni tartiblang: da’vo → dalil → talqin.","tokens":["The timetable caused the first delay.","Rain later closed the route.","One better decision would not have controlled every outcome."],"answers":["The timetable caused the first delay.\nRain later closed the route.\nOne better decision would not have controlled every outcome."],"hint":"Da’vo nimani aytadi? Dalil nimani ko‘rsatadi?","explanation":"Dalil yakuniy xulosaning o‘rnini bosmaydi; talqin ularning aloqasini tushuntiradi."},{"id":"en-b2-03-collocations","type":"collocation","skill":"vocabulary","prompt":"So‘zlarni darsdagi birikmasi bilan moslang.","left":["alternative","overlook","regret","prevent"],"options":["an alternative outcome","overlook a change","express regret","prevent a delay"],"answers":["an alternative outcome","overlook a change","express regret","prevent a delay"],"hint":"So‘z qaysi birikmada ishlatilishini eslang.","explanation":"Birikmani yozgan gapingizda ham ishlating."}],"reading":{"title":"Asosiy matn va muallif pozitsiyasi","text":"Our group missed the early bus because we used an old timetable. If we had checked the current timetable, we would have noticed the change. It is tempting to say that checking would have made the whole trip successful. That is less certain: heavy rain later closed the walking route. The mistake caused one delay, but it was not the only difficulty. During the review, the group separates facts from imagined alternatives. We know that the bus time changed. We can reasonably say that checking might have prevented the first delay. We cannot claim that it would have prevented the rain. This distinction makes the review useful rather than an exercise in blame. Next time, one person will verify transport information and another will check whether the route is open.","sentences":["Our group missed the early bus because we used an old timetable.","If we had checked the current timetable, we would have noticed the change.","It is tempting to say that checking would have made the whole trip successful.","That is less certain: heavy rain later closed the walking route.","The mistake caused one delay, but it was not the only difficulty.","During the review, the group separates facts from imagined alternatives.","We know that the bus time changed.","We can reasonably say that checking might have prevented the first delay.","We cannot claim that it would have prevented the rain.","This distinction makes the review useful rather than an exercise in blame.","Next time, one person will verify transport information and another will check whether the route is open."],"questions":[{"id":"en-b2-03-reading0","type":"choice","skill":"reading","prompt":"Nimani ishonchli aytish mumkin?","answers":["checking could have prevented the first delay"],"explanation":"Birinchi kechikish manbasi ma’lum.","hint":"If we had checked, we would have noticed.","options":["checking could have prevented the first delay","checking would have stopped the rain","the old timetable was correct"]},{"id":"en-b2-03-reading1","type":"choice","skill":"reading","prompt":"Review maqsadi?","answers":["learn without oversimplifying blame"],"explanation":"Sabablar ajratiladi.","hint":"If we had checked, we would have noticed.","options":["learn without oversimplifying blame","prove weather was controlled","cancel every trip"]},{"id":"en-b2-03-evidence","type":"evidence","skill":"reading","prompt":"Vaziyatni tanishtiradigan birinchi jumlani tanlang.","answers":["0"],"explanation":"Birinchi jumla matn vaziyatini tanishtiradi; keyingi jumlalar uni rivojlantiradi.","hint":"If we had checked, we would have noticed.","options":["Our group missed the early bus because we used an old timetable.","If we had checked the current timetable, we would have noticed the change.","It is tempting to say that checking would have made the whole trip successful.","That is less certain: heavy rain later closed the walking route.","The mistake caused one delay, but it was not the only difficulty.","During the review, the group separates facts from imagined alternatives.","We know that the bus time changed.","We can reasonably say that checking might have prevented the first delay.","We cannot claim that it would have prevented the rain.","This distinction makes the review useful rather than an exercise in blame.","Next time, one person will verify transport information and another will check whether the route is open."]}]},"listening":{"title":"Boshqa nuqtayi nazarni tinglang","transcript":"We missed the bus because the timetable was old. If we had checked, we might have avoided that delay. But the route later closed because of rain. Better planning would not have controlled the weather, so we should not blame one person for the whole outcome.","audio":"/english-course/v7.23/en-b2-03.mp3","synthetic":true,"questions":[{"id":"en-b2-03-listening0","type":"choice","skill":"listening","prompt":"Nima eski edi?","answers":["the timetable"],"explanation":"Old timetable.","hint":"If we had checked, we would have noticed.","options":["the timetable","the bus","the route"]},{"id":"en-b2-03-listening1","type":"choice","skill":"listening","prompt":"Nima nazoratda emas?","answers":["the weather"],"explanation":"Ob-havo nazoratdan tashqari.","hint":"If we had checked, we would have noticed.","options":["the weather","checking information","sharing tasks"]},{"id":"en-b2-03-audio-table","type":"table","skill":"listening","prompt":"Tinglangan ma’lumotni jadvalga yozing.","answers":["old timetable","rain"],"explanation":"Jadvaldagi javoblar yozuvda aynan aytilgan. Mavjud bo‘lmagan tafsilotni taxmin qilmang.","hint":"If we had checked, we would have noticed.","rows":["Birinchi sabab","Keyingi to‘siq"]},{"id":"en-b2-03-dictation","type":"dictation","skill":"listening","prompt":"Eshitgan gapingizni yozing.","answers":["They could have waited if they had known."],"explanation":"Gapdagi asosiy so‘zlar, yordamchi fe’l va inkor saqlanishi kerak.","hint":"If we had checked, we would have noticed.","audio":"/english-course/v7.23/en-b2-03-dictation.mp3","transcript":"They could have waited if they had known."}]},"writing":{"task":"O‘tmishdagi muvaffaqiyatsiz reja haqida review: fakt, muqobil natija va ikki kelgusi amal.","audience":"Maktab kengashi yoki loyiha guruhi","minWords":90,"maxWords":320,"plan":["Da’vo va maqsadni aniqlang.","Reading va listeningdan bir dalilni qiyoslang.","Cheklov yoki qarshi fikrni tushuntiring.","Auditoriyaga mos amaliy xulosa yozing."],"model":"Our trip was delayed because we used an old timetable. If we had checked the current version, we would have noticed the earlier departure. This might have prevented the first delay. However, it would not have kept the walking route open during the rain. We should therefore avoid treating one mistake as the cause of every problem. For the next trip, one person will verify transport information on the day before departure, while another will check the route conditions. The purpose of this review is to improve decisions, rather than simply identify someone to blame for an outcome affected by several factors.","modelNotes":["Kirishda auditoriya va maqsad aniq.","Asosiy qism dalilni talqin bilan bog‘laydi.","Yakun haddan tashqari umumlashtirmaydi."],"phrases":["If we had checked the timetable, we would have noticed the change.","We would have arrived earlier if we had left at eight.","If I had asked, she might have helped."],"checklist":["Topshiriq va auditoriyaga mos yozdim.","Fikrni o‘z so‘zlarim bilan ifodaladim.","Darsdagi shaklni to‘g‘ri ishlatdim.","Imlo, bog‘lanish va tinish belgilarini tekshirdim."]},"speaking":{"task":"Sherigingizning o‘tmish haqidagi haddan tashqari qat’iy xulosasini muloyim tuzating.","seconds":100,"prompts":["Reading va listening qayerda mos, qayerda farqli?","Sherigingizning e’tiroziga javob bering.","Qaysi dalil xulosangizni o‘zgartirishi mumkin?"],"rubric":["Vazifani bajarish","Til vositalari va aniqlik","Bog‘langan, tushunarli nutq","Talaffuz va muloqot"]},"rubrics":{"writing":["Mazmun va vazifani bajarish","Tuzilish va bog‘lanish","Til vositalari va uslub","Grammatika va imlo"],"speaking":["Vazifa va o‘zaro muloqot","Ravonlik va bog‘lanish","Til vositalari va aniqlik","Tushunarlilik va talaffuz"]},"realTask":"O‘tmishdagi muvaffaqiyatsiz reja haqida review: fakt, muqobil natija va ikki kelgusi amal.","exit":[[{"id":"en-b2-03-exit0","type":"grammarFill","skill":"grammar","prompt":"If we had ___, we would have noticed. (check)","answers":["checked"],"explanation":"If + had + V3, would have + V3 sodir bo‘lmagan o‘tmishning taxminiy natijasi. Would if qismida odatiy third conditional shakli emas. Muqobil natija taxmin: haqiqiy tarix sifatida aytmang; could yoki might ehtimolni o‘zgartiradi.","hint":"If we had checked, we would have noticed."},{"id":"en-b2-03-exit1","type":"grammarFill","skill":"grammar","prompt":"We would have ___ earlier. (arrive)","answers":["arrived"],"explanation":"If + had + V3, would have + V3 sodir bo‘lmagan o‘tmishning taxminiy natijasi. Would if qismida odatiy third conditional shakli emas. Muqobil natija taxmin: haqiqiy tarix sifatida aytmang; could yoki might ehtimolni o‘zgartiradi.","hint":"If we had checked, we would have noticed."},{"id":"en-b2-03-exit2","type":"grammarFill","skill":"grammar","prompt":"If I ___ asked, she might have helped.","answers":["had"],"explanation":"If + had + V3, would have + V3 sodir bo‘lmagan o‘tmishning taxminiy natijasi. Would if qismida odatiy third conditional shakli emas. Muqobil natija taxmin: haqiqiy tarix sifatida aytmang; could yoki might ehtimolni o‘zgartiradi.","hint":"If we had checked, we would have noticed."},{"id":"en-b2-03-exit3","type":"choice","skill":"grammar","prompt":"Ehtiyotkor muqobil xulosa?","answers":["Checking might have prevented the delay."],"explanation":"Might cheklangan ehtimol.","hint":"If we had checked, we would have noticed.","options":["Checking might have prevented the delay.","Checking would have stopped the rain.","The delay never happened."]},{"id":"en-b2-03-exit4","type":"choice","skill":"grammar","prompt":"Review maqsadi?","answers":["learn without oversimplifying blame"],"explanation":"Sabablar ajratiladi.","hint":"If we had checked, we would have noticed.","options":["learn without oversimplifying blame","prove weather was controlled","cancel every trip"]}],[{"id":"en-b2-03-exit-b0","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["We would have arrived earlier if we had left at eight."],"explanation":"If + had + V3, would have + V3 sodir bo‘lmagan o‘tmishning taxminiy natijasi. Would if qismida odatiy third conditional shakli emas. Muqobil natija taxmin: haqiqiy tarix sifatida aytmang; could yoki might ehtimolni o‘zgartiradi.","hint":"If we had checked, we would have noticed.","tokens":["We","would","have","arrived","earlier","if","we","had","left","at","eight."]},{"id":"en-b2-03-exit-b1","type":"grammarFill","skill":"grammar","prompt":"We would have ___ earlier. (arrive)","answers":["arrived"],"explanation":"If + had + V3, would have + V3 sodir bo‘lmagan o‘tmishning taxminiy natijasi. Would if qismida odatiy third conditional shakli emas. Muqobil natija taxmin: haqiqiy tarix sifatida aytmang; could yoki might ehtimolni o‘zgartiradi.","hint":"If we had checked, we would have noticed."},{"id":"en-b2-03-exit-b2","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["They could have waited if they had known."],"explanation":"If + had + V3, would have + V3 sodir bo‘lmagan o‘tmishning taxminiy natijasi. Would if qismida odatiy third conditional shakli emas. Muqobil natija taxmin: haqiqiy tarix sifatida aytmang; could yoki might ehtimolni o‘zgartiradi.","hint":"If we had checked, we would have noticed.","tokens":["They","could","have","waited","if","they","had","known."]},{"id":"en-b2-03-exit-b3","type":"choice","skill":"grammar","prompt":"Ehtiyotkor muqobil xulosa?","answers":["Checking might have prevented the delay."],"explanation":"Might cheklangan ehtimol.","hint":"If we had checked, we would have noticed.","options":["Checking might have prevented the delay.","Checking would have stopped the rain.","The delay never happened."]},{"id":"en-b2-03-exit-b4","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["The trip would not have failed if the bus had arrived."],"explanation":"If + had + V3, would have + V3 sodir bo‘lmagan o‘tmishning taxminiy natijasi. Would if qismida odatiy third conditional shakli emas. Muqobil natija taxmin: haqiqiy tarix sifatida aytmang; could yoki might ehtimolni o‘zgartiradi.","hint":"If we had checked, we would have noticed.","tokens":["The","trip","would","not","have","failed","if","the","bus","had","arrived."]}]],"sources":[{"id":"cefr","name":"Council of Europe — CEFR daraja tavsiflari","levels":["PRE","A1","A2","B1","B2","C1"],"skill":"framework","url":"https://www.coe.int/en/web/common-european-framework-reference-languages/level-descriptions","task":"Dars maqsadini qila olaman tavsifi bilan solishtiring. PRE — kursning tayyorlov bosqichi.","lesson":"en-b2-03","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"pronunciation","name":"Cambridge Dictionary — Pronunciation","levels":["PRE","A1","A2","B1","B2","C1"],"skill":"pronunciation","url":"https://dictionary.cambridge.org/pronunciation/","task":"Darsdan ikki so‘z tanlang, UK/US talaffuzini eshiting va urg‘uni qayd eting.","lesson":"en-b2-03","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-grammar","name":"British Council — Grammar","levels":["A1","A2","B1","B2","C1"],"skill":"grammar","url":"https://learnenglish.britishcouncil.org/free-resources/grammar","task":"Darajangizdagi dars mavzusini toping va bitta o‘xshash misol yozing.","lesson":"en-b2-03","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-read","name":"British Council — Reading","levels":["A1","A2","B1","B2","C1"],"skill":"reading","url":"https://learnenglish.britishcouncil.org/free-resources/reading","task":"O‘z darajangizdagi matnni tanlang; asosiy fikr va bitta dalilni ajrating.","lesson":"en-b2-03","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-write","name":"British Council — Writing","levels":["A1","A2","B1","B2","C1"],"skill":"writing","url":"https://learnenglish.britishcouncil.org/free-resources/writing","task":"Darajangizdagi namunaning kirish, asosiy qism va yakunini tahlil qiling.","lesson":"en-b2-03","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-speak","name":"British Council — Speaking (A1–B2)","levels":["A1","A2","B1","B2"],"skill":"speaking","url":"https://learnenglish.britishcouncil.org/free-resources/speaking","task":"Darajangizdagi video vaziyatidan ikki iborani o‘z dialogingizda ishlating.","lesson":"en-b2-03","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-listen","name":"British Council — Listening (A1–C1)","levels":["A1","A2","B1","B2","C1"],"skill":"listening","url":"https://learnenglish.britishcouncil.org/free-resources/listening","task":"Mos daraja audiosini transkriptsiz tinglang; keyin yozuv bilan tekshiring.","lesson":"en-b2-03","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"cambridge","name":"Cambridge English — Activities","levels":["A1","A2","B1","B2","C1"],"skill":"integrated","url":"https://www.cambridgeenglish.org/learning-english/activities-for-learners/","task":"A1–A2, B1–B2 yoki C1–C2 filtrini qo‘llang; dars ko‘nikmasiga mos mashqni tanlang.","lesson":"en-b2-03","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."}],"recapEvery":4,"project":false,"rights":"Original SinfQuiz content; local Flite synthetic speech. Educational references are linked, not copied."}'::jsonb) on conflict(id,revision) do nothing;
insert into public.sq_en_content(id,base_id,owner_id,level,ordinal,status,revision,payload) values('en-b2-04','en-b2-04',null,4,4,'published',1,'{"id":"en-b2-04","baseId":"en-b2-04","revision":1,"level":"B2","levelIndex":4,"order":4,"title":"Mixed Conditional: o‘tmish va hozir","objective":"O‘tgan qarorning hozirgi oqibatini aniq vaqt aloqasi bilan ifodalaysiz.","context":"Ko‘nikma o‘rganishga kech boshlagan ishtirokchi.","prerequisites":["en-b2-03"],"minutes":55,"skills":["grammar","vocabulary","pronunciation","listening","reading","writing","speaking"],"rules":["If + had + V3, would + V hozirgi natijaga ulanadi: If I had practised, I would be more confident now.","If + past simple, would have + V3 doimiy yoki hozirgi holatning o‘tgan natijaga ta’sirini bildirishi mumkin.","Natija vaqtini now yoki yesterday bilan tekshiring; qolipni vaqt ma’nosiz aralashtirmang."],"pattern":"past choice → present result: had practised / would feel now","examples":["If I had practised earlier, I would feel more confident now.","If she knew the software, she would have helped yesterday.","We would be ready now if we had started sooner.","If I were more organised, I would have found the file.","He would not be tired now if he had slept longer.","If we had saved the data, we would have it today."],"vocabulary":[{"id":"en-b2-04-v0","term":"confidence","meaning":"ishonch","ipa":"/ˈkɒnfɪdəns/","collocation":"build confidence","example":"The review connects past preparation to present confidence without turning confidence into a fixed personal quality."},{"id":"en-b2-04-v1","term":"consequence","meaning":"oqibat","ipa":"/ˈkɒnsɪkwəns/","collocation":"a present consequence","example":"a present consequence"},{"id":"en-b2-04-v2","term":"preparation","meaning":"tayyorgarlik","ipa":"/ˌprepəˈreɪʃən/","collocation":"earlier preparation","example":"The review connects past preparation to present confidence without turning confidence into a fixed personal quality."},{"id":"en-b2-04-v3","term":"adjust","meaning":"moslashtirmoq","ipa":"/əˈdʒʌst/","collocation":"adjust a plan","example":"adjust a plan"}],"visuals":[{"kind":"timeline","title":"Ma’no va tuzilish","items":["past choice → present result: had practised / would feel now","If I had practised earlier, I would feel more confident now.","If she knew the software, she would have helped yesterday."],"timeline":[{"why":"If I had practised — amalga oshmagan o‘tgan shart; would feel now — taxminiy hozirgi natija. Bu chiziq haqiqiy voqea emas.","events":[{"kind":"point","x":130,"label":"Amalga oshmagan o‘tgan shart"},{"kind":"link","from":130,"to":320,"label":"Taxminiy hozirgi natija"}]},{"why":"If she knew — hozirgi bilimga oid noreal shart; would have helped yesterday — taxminiy o‘tgan natija.","events":[{"kind":"point","x":170,"label":"Taxminiy kechagi yordam"},{"kind":"link","from":320,"to":170,"label":"Noreal shart → o‘tgan natija"}]}]},{"kind":"argument","title":"Fikr va dalilning aloqasi","items":["Earlier preparation affects confidence now.","Lola can still explain the topic.","The team can adjust roles and practise."]}],"pronunciation":{"focus":"Gapdagi mazmunli so‘zlarni urg‘u bilan ayting. Nuqtada to‘xtab, yozuvni qayta tinglang.","text":"If I were more organised, I would have found the file.","audio":"/english-course/v7.23/en-b2-04-dictation.mp3"},"exercises":[{"id":"en-b2-04-choice","type":"choice","skill":"grammar","prompt":"Til vositasini tanlang: If I had practised, I would ___ confident now. (feel)","answers":["feel"],"explanation":"If + had + V3, would + V hozirgi natijaga ulanadi: If I had practised, I would be more confident now. If + past simple, would have + V3 doimiy yoki hozirgi holatning o‘tgan natijaga ta’sirini bildirishi mumkin. Natija vaqtini now yoki yesterday bilan tekshiring; qolipni vaqt ma’nosiz aralashtirmang.","hint":"past choice → present result: had practised / would feel now","options":["feel","felt","feeling"]},{"id":"en-b2-04-gap","type":"grammarFill","skill":"grammar","prompt":"If I had practised, I would ___ confident now. (feel)","answers":["feel"],"explanation":"If + had + V3, would + V hozirgi natijaga ulanadi: If I had practised, I would be more confident now. If + past simple, would have + V3 doimiy yoki hozirgi holatning o‘tgan natijaga ta’sirini bildirishi mumkin. Natija vaqtini now yoki yesterday bilan tekshiring; qolipni vaqt ma’nosiz aralashtirmang.","hint":"past choice → present result: had practised / would feel now"},{"id":"en-b2-04-order","type":"order","skill":"grammar","prompt":"Kartalarni to‘g‘ri tartibga qo‘ying.","answers":["If I had practised earlier, I would feel more confident now."],"explanation":"If + had + V3, would + V hozirgi natijaga ulanadi: If I had practised, I would be more confident now. If + past simple, would have + V3 doimiy yoki hozirgi holatning o‘tgan natijaga ta’sirini bildirishi mumkin. Natija vaqtini now yoki yesterday bilan tekshiring; qolipni vaqt ma’nosiz aralashtirmang.","hint":"past choice → present result: had practised / would feel now","tokens":["If","I","had","practised","earlier,","I","would","feel","more","confident","now."]},{"id":"en-b2-04-fix","type":"correction","skill":"grammar","prompt":"If I had practised, I would have feel confident now.","answers":["If I had practised, I would feel confident now."],"explanation":"If + had + V3, would + V hozirgi natijaga ulanadi: If I had practised, I would be more confident now. If + past simple, would have + V3 doimiy yoki hozirgi holatning o‘tgan natijaga ta’sirini bildirishi mumkin. Natija vaqtini now yoki yesterday bilan tekshiring; qolipni vaqt ma’nosiz aralashtirmang.","hint":"past choice → present result: had practised / would feel now"},{"id":"en-b2-04-vocabulary","type":"matching","skill":"vocabulary","prompt":"So‘zlarni ma’nolari bilan moslang.","answers":["ishonch","oqibat","tayyorgarlik","moslashtirmoq"],"explanation":"So‘zni alohida emas, darsdagi birikma va gap bilan eslang.","hint":"past choice → present result: had practised / would feel now","left":["confidence","consequence","preparation","adjust"],"options":["ishonch","oqibat","tayyorgarlik","moslashtirmoq"]},{"id":"en-b2-04-transform","type":"transformation","skill":"grammar","prompt":"Now natija bilan birlashtiring: I did not practise earlier. I am not confident now.","answers":["If I had practised earlier, I would be confident now."],"hint":"past choice → present result: had practised / would feel now","explanation":"If + had + V3, would + V hozirgi natijaga ulanadi: If I had practised, I would be more confident now."},{"id":"en-b2-04-paragraphs","type":"paragraphOrder","skill":"reading","prompt":"Fikrni tartiblang: da’vo → dalil → talqin.","tokens":["Earlier preparation affects confidence now.","Lola can still explain the topic.","The team can adjust roles and practise."],"answers":["Earlier preparation affects confidence now.\nLola can still explain the topic.\nThe team can adjust roles and practise."],"hint":"Da’vo nimani aytadi? Dalil nimani ko‘rsatadi?","explanation":"Dalil yakuniy xulosaning o‘rnini bosmaydi; talqin ularning aloqasini tushuntiradi."},{"id":"en-b2-04-dialogue","type":"dialogue","skill":"grammar","prompt":"Sherik: “Can you give one example?” Siz: darsdagi birinchi namunani qayta tuzing.","answers":["If I had practised earlier, I would feel more confident now."],"tokens":["If","I","had","practised","earlier,","I","would","feel","more","confident","now."],"hint":"past choice → present result: had practised / would feel now","explanation":"If + had + V3, would + V hozirgi natijaga ulanadi: If I had practised, I would be more confident now."},{"id":"en-b2-04-recap-0","type":"choice","skill":"grammar","prompt":"Takrorlash · Aspect: natija va jarayonni tanlash: Til vositasini tanlang: We have ___ three shelves. (repair)","answers":["repaired"],"explanation":"Perfect simple tugallangan natija yoki miqdorga, perfect continuous esa jarayon va davomiylikka e’tibor beradi. I have painted three walls va I have been painting walls bir vaziyatning turli tomonlarini ko‘rsatadi. For ikki shaklda ham kelishi mumkin; shaklni faqat vaqt so‘ziga qarab tanlamang.","hint":"have completed / have been working","options":["repaired","repairing","repair"],"recap":true,"sourceLesson":"Aspect: natija va jarayonni tanlash"},{"id":"en-b2-04-recap-1","type":"choice","skill":"grammar","prompt":"Takrorlash · Future Continuous va Future Perfect: Til vositasini tanlang: At ten we will be ___ displays. (arrange)","answers":["arranging"],"explanation":"Will be + -ing kelajakdagi bir vaqtda davom etayotgan ishni ko‘rsatadi. Will have + V3 kelajak nuqtasigacha tugallangan natijani bildiradi. By Friday — juma kelguncha; at ten — o‘n paytida. Muddat real reja bilan mos bo‘lsin.","hint":"at ten: will be preparing / by ten: will have prepared","options":["arranging","arranged","arrange"],"recap":true,"sourceLesson":"Future Continuous va Future Perfect"},{"id":"en-b2-04-recap-2","type":"choice","skill":"grammar","prompt":"Takrorlash · Third Conditional: bo‘lmagan o‘tmish: Til vositasini tanlang: If we had ___, we would have noticed. (check)","answers":["checked"],"explanation":"If + had + V3, would have + V3 sodir bo‘lmagan o‘tmishning taxminiy natijasi. Would if qismida odatiy third conditional shakli emas. Muqobil natija taxmin: haqiqiy tarix sifatida aytmang; could yoki might ehtimolni o‘zgartiradi.","hint":"If we had checked, we would have noticed.","options":["checked","checking","check"],"recap":true,"sourceLesson":"Third Conditional: bo‘lmagan o‘tmish"}],"reading":{"title":"Asosiy matn va muallif pozitsiyasi","text":"Lola joined the presentation team only last week. She understands the topic but feels nervous using the software. If she had practised earlier, she would feel more confident now. This does not mean that she cannot contribute. Another student knows the software well but struggles to explain ideas clearly. Their skills are different, so the group changes the plan: Lola explains the argument while her partner operates the slides. The review connects past preparation to present confidence without turning confidence into a fixed personal quality. The group also plans short practice sessions for the next meeting. If preparation had begun earlier, today’s rehearsal would be easier; since it did not, they can still make useful choices now. A mixed conditional helps describe the time connection, but a practical plan must follow it.","sentences":["Lola joined the presentation team only last week.","She understands the topic but feels nervous using the software.","If she had practised earlier, she would feel more confident now.","This does not mean that she cannot contribute.","Another student knows the software well but struggles to explain ideas clearly.","Their skills are different, so the group changes the plan: Lola explains the argument while her partner operates the slides.","The review connects past preparation to present confidence without turning confidence into a fixed personal quality.","The group also plans short practice sessions for the next meeting.","If preparation had begun earlier, today’s rehearsal would be easier; since it did not, they can still make useful choices now.","A mixed conditional helps describe the time connection, but a practical plan must follow it."],"questions":[{"id":"en-b2-04-reading0","type":"choice","skill":"reading","prompt":"Hozirgi muammo nima?","answers":["confidence with software"],"explanation":"Topic tushunarli, dasturda ishonch kam.","hint":"past choice → present result: had practised / would feel now","options":["confidence with software","no knowledge of the topic","no partner"]},{"id":"en-b2-04-reading1","type":"choice","skill":"reading","prompt":"Guruh qanday yechim topdi?","answers":["divide roles according to skills"],"explanation":"Rollar turli ko‘nikmalarga mos.","hint":"past choice → present result: had practised / would feel now","options":["divide roles according to skills","exclude Lola","avoid practice forever"]},{"id":"en-b2-04-evidence","type":"evidence","skill":"reading","prompt":"Vaziyatni tanishtiradigan birinchi jumlani tanlang.","answers":["0"],"explanation":"Birinchi jumla matn vaziyatini tanishtiradi; keyingi jumlalar uni rivojlantiradi.","hint":"past choice → present result: had practised / would feel now","options":["Lola joined the presentation team only last week.","She understands the topic but feels nervous using the software.","If she had practised earlier, she would feel more confident now.","This does not mean that she cannot contribute.","Another student knows the software well but struggles to explain ideas clearly.","Their skills are different, so the group changes the plan: Lola explains the argument while her partner operates the slides.","The review connects past preparation to present confidence without turning confidence into a fixed personal quality.","The group also plans short practice sessions for the next meeting.","If preparation had begun earlier, today’s rehearsal would be easier; since it did not, they can still make useful choices now.","A mixed conditional helps describe the time connection, but a practical plan must follow it."]}]},"listening":{"title":"Boshqa nuqtayi nazarni tinglang","transcript":"If Lola had practised the software earlier, she would feel more confident now. But she explains ideas clearly, so she will present while her partner handles the slides. We will also arrange short practice sessions for next week.","audio":"/english-course/v7.23/en-b2-04.mp3","synthetic":true,"questions":[{"id":"en-b2-04-listening0","type":"choice","skill":"listening","prompt":"Slaydni kim boshqaradi?","answers":["her partner"],"explanation":"Partner handles slides.","hint":"past choice → present result: had practised / would feel now","options":["her partner","no one","Lola only"]},{"id":"en-b2-04-listening1","type":"choice","skill":"listening","prompt":"Kelgusi yechim?","answers":["short practice sessions"],"explanation":"Practice sessions.","hint":"past choice → present result: had practised / would feel now","options":["short practice sessions","stop presenting","buy new software only"]},{"id":"en-b2-04-audio-table","type":"table","skill":"listening","prompt":"Tinglangan ma’lumotni jadvalga yozing.","answers":["present","next week"],"explanation":"Jadvaldagi javoblar yozuvda aynan aytilgan. Mavjud bo‘lmagan tafsilotni taxmin qilmang.","hint":"past choice → present result: had practised / would feel now","rows":["Lola vazifasi","Mashq muddati"]},{"id":"en-b2-04-dictation","type":"dictation","skill":"listening","prompt":"Eshitgan gapingizni yozing.","answers":["If I were more organised, I would have found the file."],"explanation":"Gapdagi asosiy so‘zlar, yordamchi fe’l va inkor saqlanishi kerak.","hint":"past choice → present result: had practised / would feel now","audio":"/english-course/v7.23/en-b2-04-dictation.mp3","transcript":"If I were more organised, I would have found the file."}]},"writing":{"task":"Bir o‘tgan qarorning hozirgi oqibatini va hozir qilish mumkin bo‘lgan amallarni yozing.","audience":"Maktab kengashi yoki loyiha guruhi","minWords":90,"maxWords":320,"plan":["Da’vo va maqsadni aniqlang.","Reading va listeningdan bir dalilni qiyoslang.","Cheklov yoki qarshi fikrni tushuntiring.","Auditoriyaga mos amaliy xulosa yozing."],"model":"If I had practised the presentation software earlier, I would feel more confident now. However, I understand the topic and can explain the main argument clearly. Our group has therefore divided the tasks according to our strengths. I will present the ideas while my partner handles the slides. This arrangement solves the immediate problem, but it should not replace learning the missing skill. We will hold two short practice sessions before the next meeting. The past decision cannot be changed; the present plan can. I want our review to explain the consequence accurately without treating a temporary difficulty as a permanent weakness.","modelNotes":["Kirishda auditoriya va maqsad aniq.","Asosiy qism dalilni talqin bilan bog‘laydi.","Yakun haddan tashqari umumlashtirmaydi."],"phrases":["If I had practised earlier, I would feel more confident now.","If she knew the software, she would have helped yesterday.","We would be ready now if we had started sooner."],"checklist":["Topshiriq va auditoriyaga mos yozdim.","Fikrni o‘z so‘zlarim bilan ifodaladim.","Darsdagi shaklni to‘g‘ri ishlatdim.","Imlo, bog‘lanish va tinish belgilarini tekshirdim."]},"speaking":{"task":"Hozirgi muammoni o‘tmish sababiga bog‘lang, so‘ng amaliy yechim taklif qiling.","seconds":100,"prompts":["Reading va listening qayerda mos, qayerda farqli?","Sherigingizning e’tiroziga javob bering.","Qaysi dalil xulosangizni o‘zgartirishi mumkin?"],"rubric":["Vazifani bajarish","Til vositalari va aniqlik","Bog‘langan, tushunarli nutq","Talaffuz va muloqot"]},"rubrics":{"writing":["Mazmun va vazifani bajarish","Tuzilish va bog‘lanish","Til vositalari va uslub","Grammatika va imlo"],"speaking":["Vazifa va o‘zaro muloqot","Ravonlik va bog‘lanish","Til vositalari va aniqlik","Tushunarlilik va talaffuz"]},"realTask":"Bir o‘tgan qarorning hozirgi oqibatini va hozir qilish mumkin bo‘lgan amallarni yozing.","exit":[[{"id":"en-b2-04-exit0","type":"grammarFill","skill":"grammar","prompt":"If I had practised, I would ___ confident now. (feel)","answers":["feel"],"explanation":"If + had + V3, would + V hozirgi natijaga ulanadi: If I had practised, I would be more confident now. If + past simple, would have + V3 doimiy yoki hozirgi holatning o‘tgan natijaga ta’sirini bildirishi mumkin. Natija vaqtini now yoki yesterday bilan tekshiring; qolipni vaqt ma’nosiz aralashtirmang.","hint":"past choice → present result: had practised / would feel now"},{"id":"en-b2-04-exit1","type":"grammarFill","skill":"grammar","prompt":"If she ___ the software, she would have helped yesterday. (know)","answers":["knew"],"explanation":"If + had + V3, would + V hozirgi natijaga ulanadi: If I had practised, I would be more confident now. If + past simple, would have + V3 doimiy yoki hozirgi holatning o‘tgan natijaga ta’sirini bildirishi mumkin. Natija vaqtini now yoki yesterday bilan tekshiring; qolipni vaqt ma’nosiz aralashtirmang.","hint":"past choice → present result: had practised / would feel now"},{"id":"en-b2-04-exit2","type":"grammarFill","skill":"grammar","prompt":"We would be ready now if we ___ started sooner.","answers":["had"],"explanation":"If + had + V3, would + V hozirgi natijaga ulanadi: If I had practised, I would be more confident now. If + past simple, would have + V3 doimiy yoki hozirgi holatning o‘tgan natijaga ta’sirini bildirishi mumkin. Natija vaqtini now yoki yesterday bilan tekshiring; qolipni vaqt ma’nosiz aralashtirmang.","hint":"past choice → present result: had practised / would feel now"},{"id":"en-b2-04-exit3","type":"choice","skill":"grammar","prompt":"O‘tmishdan hozirga bog‘lanish?","answers":["If we had saved it, we would have it today."],"explanation":"Had saved → would have today.","hint":"past choice → present result: had practised / would feel now","options":["If we had saved it, we would have it today.","If we save it, we will have it tomorrow.","We saved it yesterday."]},{"id":"en-b2-04-exit4","type":"choice","skill":"grammar","prompt":"Guruh qanday yechim topdi?","answers":["divide roles according to skills"],"explanation":"Rollar turli ko‘nikmalarga mos.","hint":"past choice → present result: had practised / would feel now","options":["divide roles according to skills","exclude Lola","avoid practice forever"]}],[{"id":"en-b2-04-exit-b0","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["If she knew the software, she would have helped yesterday."],"explanation":"If + had + V3, would + V hozirgi natijaga ulanadi: If I had practised, I would be more confident now. If + past simple, would have + V3 doimiy yoki hozirgi holatning o‘tgan natijaga ta’sirini bildirishi mumkin. Natija vaqtini now yoki yesterday bilan tekshiring; qolipni vaqt ma’nosiz aralashtirmang.","hint":"past choice → present result: had practised / would feel now","tokens":["If","she","knew","the","software,","she","would","have","helped","yesterday."]},{"id":"en-b2-04-exit-b1","type":"grammarFill","skill":"grammar","prompt":"If she ___ the software, she would have helped yesterday. (know)","answers":["knew"],"explanation":"If + had + V3, would + V hozirgi natijaga ulanadi: If I had practised, I would be more confident now. If + past simple, would have + V3 doimiy yoki hozirgi holatning o‘tgan natijaga ta’sirini bildirishi mumkin. Natija vaqtini now yoki yesterday bilan tekshiring; qolipni vaqt ma’nosiz aralashtirmang.","hint":"past choice → present result: had practised / would feel now"},{"id":"en-b2-04-exit-b2","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["If I were more organised, I would have found the file."],"explanation":"If + had + V3, would + V hozirgi natijaga ulanadi: If I had practised, I would be more confident now. If + past simple, would have + V3 doimiy yoki hozirgi holatning o‘tgan natijaga ta’sirini bildirishi mumkin. Natija vaqtini now yoki yesterday bilan tekshiring; qolipni vaqt ma’nosiz aralashtirmang.","hint":"past choice → present result: had practised / would feel now","tokens":["If","I","were","more","organised,","I","would","have","found","the","file."]},{"id":"en-b2-04-exit-b3","type":"choice","skill":"grammar","prompt":"O‘tmishdan hozirga bog‘lanish?","answers":["If we had saved it, we would have it today."],"explanation":"Had saved → would have today.","hint":"past choice → present result: had practised / would feel now","options":["If we had saved it, we would have it today.","If we save it, we will have it tomorrow.","We saved it yesterday."]},{"id":"en-b2-04-exit-b4","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["If we had saved the data, we would have it today."],"explanation":"If + had + V3, would + V hozirgi natijaga ulanadi: If I had practised, I would be more confident now. If + past simple, would have + V3 doimiy yoki hozirgi holatning o‘tgan natijaga ta’sirini bildirishi mumkin. Natija vaqtini now yoki yesterday bilan tekshiring; qolipni vaqt ma’nosiz aralashtirmang.","hint":"past choice → present result: had practised / would feel now","tokens":["If","we","had","saved","the","data,","we","would","have","it","today."]}]],"sources":[{"id":"cefr","name":"Council of Europe — CEFR daraja tavsiflari","levels":["PRE","A1","A2","B1","B2","C1"],"skill":"framework","url":"https://www.coe.int/en/web/common-european-framework-reference-languages/level-descriptions","task":"Dars maqsadini qila olaman tavsifi bilan solishtiring. PRE — kursning tayyorlov bosqichi.","lesson":"en-b2-04","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"pronunciation","name":"Cambridge Dictionary — Pronunciation","levels":["PRE","A1","A2","B1","B2","C1"],"skill":"pronunciation","url":"https://dictionary.cambridge.org/pronunciation/","task":"Darsdan ikki so‘z tanlang, UK/US talaffuzini eshiting va urg‘uni qayd eting.","lesson":"en-b2-04","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-grammar","name":"British Council — Grammar","levels":["A1","A2","B1","B2","C1"],"skill":"grammar","url":"https://learnenglish.britishcouncil.org/free-resources/grammar","task":"Darajangizdagi dars mavzusini toping va bitta o‘xshash misol yozing.","lesson":"en-b2-04","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-read","name":"British Council — Reading","levels":["A1","A2","B1","B2","C1"],"skill":"reading","url":"https://learnenglish.britishcouncil.org/free-resources/reading","task":"O‘z darajangizdagi matnni tanlang; asosiy fikr va bitta dalilni ajrating.","lesson":"en-b2-04","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-write","name":"British Council — Writing","levels":["A1","A2","B1","B2","C1"],"skill":"writing","url":"https://learnenglish.britishcouncil.org/free-resources/writing","task":"Darajangizdagi namunaning kirish, asosiy qism va yakunini tahlil qiling.","lesson":"en-b2-04","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-speak","name":"British Council — Speaking (A1–B2)","levels":["A1","A2","B1","B2"],"skill":"speaking","url":"https://learnenglish.britishcouncil.org/free-resources/speaking","task":"Darajangizdagi video vaziyatidan ikki iborani o‘z dialogingizda ishlating.","lesson":"en-b2-04","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-listen","name":"British Council — Listening (A1–C1)","levels":["A1","A2","B1","B2","C1"],"skill":"listening","url":"https://learnenglish.britishcouncil.org/free-resources/listening","task":"Mos daraja audiosini transkriptsiz tinglang; keyin yozuv bilan tekshiring.","lesson":"en-b2-04","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"cambridge","name":"Cambridge English — Activities","levels":["A1","A2","B1","B2","C1"],"skill":"integrated","url":"https://www.cambridgeenglish.org/learning-english/activities-for-learners/","task":"A1–A2, B1–B2 yoki C1–C2 filtrini qo‘llang; dars ko‘nikmasiga mos mashqni tanlang.","lesson":"en-b2-04","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."}],"recapEvery":4,"project":false,"rights":"Original SinfQuiz content; local Flite synthetic speech. Educational references are linked, not copied.","recapQuestions":[{"id":"en-b2-04-recap-0","type":"choice","skill":"grammar","prompt":"Takrorlash · Aspect: natija va jarayonni tanlash: Til vositasini tanlang: We have ___ three shelves. (repair)","answers":["repaired"],"explanation":"Perfect simple tugallangan natija yoki miqdorga, perfect continuous esa jarayon va davomiylikka e’tibor beradi. I have painted three walls va I have been painting walls bir vaziyatning turli tomonlarini ko‘rsatadi. For ikki shaklda ham kelishi mumkin; shaklni faqat vaqt so‘ziga qarab tanlamang.","hint":"have completed / have been working","options":["repaired","repairing","repair"],"recap":true,"sourceLesson":"Aspect: natija va jarayonni tanlash"},{"id":"en-b2-04-recap-1","type":"choice","skill":"grammar","prompt":"Takrorlash · Future Continuous va Future Perfect: Til vositasini tanlang: At ten we will be ___ displays. (arrange)","answers":["arranging"],"explanation":"Will be + -ing kelajakdagi bir vaqtda davom etayotgan ishni ko‘rsatadi. Will have + V3 kelajak nuqtasigacha tugallangan natijani bildiradi. By Friday — juma kelguncha; at ten — o‘n paytida. Muddat real reja bilan mos bo‘lsin.","hint":"at ten: will be preparing / by ten: will have prepared","options":["arranging","arranged","arrange"],"recap":true,"sourceLesson":"Future Continuous va Future Perfect"},{"id":"en-b2-04-recap-2","type":"choice","skill":"grammar","prompt":"Takrorlash · Third Conditional: bo‘lmagan o‘tmish: Til vositasini tanlang: If we had ___, we would have noticed. (check)","answers":["checked"],"explanation":"If + had + V3, would have + V3 sodir bo‘lmagan o‘tmishning taxminiy natijasi. Would if qismida odatiy third conditional shakli emas. Muqobil natija taxmin: haqiqiy tarix sifatida aytmang; could yoki might ehtimolni o‘zgartiradi.","hint":"If we had checked, we would have noticed.","options":["checked","checking","check"],"recap":true,"sourceLesson":"Third Conditional: bo‘lmagan o‘tmish"}]}'::jsonb) on conflict(id,revision) do nothing;
insert into public.sq_en_content(id,base_id,owner_id,level,ordinal,status,revision,payload) values('en-b2-05','en-b2-05',null,4,5,'published',1,'{"id":"en-b2-05","baseId":"en-b2-05","revision":1,"level":"B2","levelIndex":4,"order":5,"title":"Wish va if only","objective":"Hozirgi afsus, o‘tmishdagi afsus va o‘zgarish istagini ajratasiz.","context":"Klub xonasidagi shovqin va reja.","prerequisites":["en-b2-04"],"minutes":55,"skills":["grammar","vocabulary","pronunciation","listening","reading","writing","speaking"],"rules":["Wish + past simple hozirgi boshqa holat istagi: I wish the room were quieter.","Wish + had + V3 o‘tgan ishga afsus: I wish we had booked earlier.","Wish + would boshqa odamning o‘zgarishi kutilgan xatti-harakatiga; oddiy o‘z qobiliyatingiz uchun could yoki past shakli."],"pattern":"wish were / wish had booked / wish would stop","examples":["I wish the room were quieter.","I wish we had booked earlier.","I wish they would lower the music.","If only I could hear the speaker.","She wishes she had checked the date.","I wish I knew another place."],"vocabulary":[{"id":"en-b2-05-v0","term":"disturb","meaning":"bezovta qilmoq","ipa":"/dɪˈstɜːb/","collocation":"disturb a meeting","example":"disturb a meeting"},{"id":"en-b2-05-v1","term":"regret","meaning":"afsus","ipa":"/rɪˈɡret/","collocation":"regret a decision","example":"The students still lose some time, but they learn to separate regret from action."},{"id":"en-b2-05-v2","term":"considerate","meaning":"e’tiborli","ipa":"/kənˈsɪdərət/","collocation":"a considerate neighbour","example":"a considerate neighbour"},{"id":"en-b2-05-v3","term":"request","meaning":"so‘rov","ipa":"/rɪˈkwest/","collocation":"make a request","example":"These sentences express different wishes, yet none is a direct request to the people who can help."}],"visuals":[{"kind":"argument","title":"Ma’no va tuzilish","items":["wish were / wish had booked / wish would stop","I wish the room were quieter.","I wish we had booked earlier."]},{"kind":"argument","title":"Fikr va dalilning aloqasi","items":["The room was too noisy for discussion.","A quieter room was available later.","Future bookings need clearer information."]}],"pronunciation":{"focus":"Gapdagi mazmunli so‘zlarni urg‘u bilan ayting. Nuqtada to‘xtab, yozuvni qayta tinglang.","text":"If only I could hear the speaker.","audio":"/english-course/v7.23/en-b2-05-dictation.mp3"},"exercises":[{"id":"en-b2-05-choice","type":"choice","skill":"grammar","prompt":"Til vositasini tanlang: I wish we ___ checked earlier.","answers":["had"],"explanation":"Wish + past simple hozirgi boshqa holat istagi: I wish the room were quieter. Wish + had + V3 o‘tgan ishga afsus: I wish we had booked earlier. Wish + would boshqa odamning o‘zgarishi kutilgan xatti-harakatiga; oddiy o‘z qobiliyatingiz uchun could yoki past shakli.","hint":"wish were / wish had booked / wish would stop","options":["had","have","has"]},{"id":"en-b2-05-gap","type":"grammarFill","skill":"grammar","prompt":"I wish we ___ checked earlier.","answers":["had"],"explanation":"Wish + past simple hozirgi boshqa holat istagi: I wish the room were quieter. Wish + had + V3 o‘tgan ishga afsus: I wish we had booked earlier. Wish + would boshqa odamning o‘zgarishi kutilgan xatti-harakatiga; oddiy o‘z qobiliyatingiz uchun could yoki past shakli.","hint":"wish were / wish had booked / wish would stop"},{"id":"en-b2-05-order","type":"order","skill":"grammar","prompt":"Kartalarni to‘g‘ri tartibga qo‘ying.","answers":["I wish the room were quieter."],"explanation":"Wish + past simple hozirgi boshqa holat istagi: I wish the room were quieter. Wish + had + V3 o‘tgan ishga afsus: I wish we had booked earlier. Wish + would boshqa odamning o‘zgarishi kutilgan xatti-harakatiga; oddiy o‘z qobiliyatingiz uchun could yoki past shakli.","hint":"wish were / wish had booked / wish would stop","tokens":["I","wish","the","room","were","quieter."]},{"id":"en-b2-05-fix","type":"correction","skill":"grammar","prompt":"I wish I would know another place.","answers":["I wish I knew another place."],"explanation":"Wish + past simple hozirgi boshqa holat istagi: I wish the room were quieter. Wish + had + V3 o‘tgan ishga afsus: I wish we had booked earlier. Wish + would boshqa odamning o‘zgarishi kutilgan xatti-harakatiga; oddiy o‘z qobiliyatingiz uchun could yoki past shakli.","hint":"wish were / wish had booked / wish would stop"},{"id":"en-b2-05-vocabulary","type":"matching","skill":"vocabulary","prompt":"So‘zlarni ma’nolari bilan moslang.","answers":["bezovta qilmoq","afsus","e’tiborli","so‘rov"],"explanation":"So‘zni alohida emas, darsdagi birikma va gap bilan eslang.","hint":"wish were / wish had booked / wish would stop","left":["disturb","regret","considerate","request"],"options":["bezovta qilmoq","afsus","e’tiborli","so‘rov"]},{"id":"en-b2-05-transform","type":"transformation","skill":"grammar","prompt":"O‘tgan afsus: We did not check the programme.","answers":["I wish we had checked the programme."],"hint":"wish were / wish had booked / wish would stop","explanation":"Wish + past simple hozirgi boshqa holat istagi: I wish the room were quieter."},{"id":"en-b2-05-paragraphs","type":"paragraphOrder","skill":"reading","prompt":"Fikrni tartiblang: da’vo → dalil → talqin.","tokens":["The room was too noisy for discussion.","A quieter room was available later.","Future bookings need clearer information."],"answers":["The room was too noisy for discussion.\nA quieter room was available later.\nFuture bookings need clearer information."],"hint":"Da’vo nimani aytadi? Dalil nimani ko‘rsatadi?","explanation":"Dalil yakuniy xulosaning o‘rnini bosmaydi; talqin ularning aloqasini tushuntiradi."}],"reading":{"title":"Asosiy matn va muallif pozitsiyasi","text":"Our club booked a small room for a discussion, but loud music from the next room made conversation difficult. Several students said they wished the room were quieter. The organiser wished she had checked the programme before booking. Another student said he wished the neighbours would lower the music. These sentences express different wishes, yet none is a direct request to the people who can help. The group therefore speaks to the venue manager and asks whether another room is available. The manager offers a quieter space for the final half of the meeting. The students still lose some time, but they learn to separate regret from action. Wishing describes dissatisfaction; a respectful request can change the situation. At the next booking, they will ask about nearby activities rather than assume the room is quiet.","sentences":["Our club booked a small room for a discussion, but loud music from the next room made conversation difficult.","Several students said they wished the room were quieter.","The organiser wished she had checked the programme before booking.","Another student said he wished the neighbours would lower the music.","These sentences express different wishes, yet none is a direct request to the people who can help.","The group therefore speaks to the venue manager and asks whether another room is available.","The manager offers a quieter space for the final half of the meeting.","The students still lose some time, but they learn to separate regret from action.","Wishing describes dissatisfaction; a respectful request can change the situation.","At the next booking, they will ask about nearby activities rather than assume the room is quiet."],"questions":[{"id":"en-b2-05-reading0","type":"choice","skill":"reading","prompt":"Nega wish yetarli emas?","answers":["it does not directly request a change"],"explanation":"Wish istak, harakat uchun so‘rov kerak.","hint":"wish were / wish had booked / wish would stop","options":["it does not directly request a change","it guarantees a new room","it changes the past"]},{"id":"en-b2-05-reading1","type":"choice","skill":"reading","prompt":"Qaysi o‘tgan qaror afsus?","answers":["not checking the programme"],"explanation":"Had checked o‘tmish.","hint":"wish were / wish had booked / wish would stop","options":["not checking the programme","lowering the music","moving to a quiet room"]},{"id":"en-b2-05-evidence","type":"evidence","skill":"reading","prompt":"Vaziyatni tanishtiradigan birinchi jumlani tanlang.","answers":["0"],"explanation":"Birinchi jumla matn vaziyatini tanishtiradi; keyingi jumlalar uni rivojlantiradi.","hint":"wish were / wish had booked / wish would stop","options":["Our club booked a small room for a discussion, but loud music from the next room made conversation difficult.","Several students said they wished the room were quieter.","The organiser wished she had checked the programme before booking.","Another student said he wished the neighbours would lower the music.","These sentences express different wishes, yet none is a direct request to the people who can help.","The group therefore speaks to the venue manager and asks whether another room is available.","The manager offers a quieter space for the final half of the meeting.","The students still lose some time, but they learn to separate regret from action.","Wishing describes dissatisfaction; a respectful request can change the situation.","At the next booking, they will ask about nearby activities rather than assume the room is quiet."]}]},"listening":{"title":"Boshqa nuqtayi nazarni tinglang","transcript":"I wish we had checked the programme before booking. The music is too loud. I wish they would lower it, but we should ask the manager for help. There is a quieter room available for the second half of our meeting.","audio":"/english-course/v7.23/en-b2-05.mp3","synthetic":true,"questions":[{"id":"en-b2-05-listening0","type":"choice","skill":"listening","prompt":"Yangi xona qachon?","answers":["the second half"],"explanation":"Second half.","hint":"wish were / wish had booked / wish would stop","options":["the second half","next year","the first five minutes"]},{"id":"en-b2-05-listening1","type":"choice","skill":"listening","prompt":"Kimdan yordam?","answers":["the manager"],"explanation":"Ask manager.","hint":"wish were / wish had booked / wish would stop","options":["the manager","the bus driver","nobody"]},{"id":"en-b2-05-audio-table","type":"table","skill":"listening","prompt":"Tinglangan ma’lumotni jadvalga yozing.","answers":["loud music","a quieter room"],"explanation":"Jadvaldagi javoblar yozuvda aynan aytilgan. Mavjud bo‘lmagan tafsilotni taxmin qilmang.","hint":"wish were / wish had booked / wish would stop","rows":["Muammo","Yechim"]},{"id":"en-b2-05-dictation","type":"dictation","skill":"listening","prompt":"Eshitgan gapingizni yozing.","answers":["If only I could hear the speaker."],"explanation":"Gapdagi asosiy so‘zlar, yordamchi fe’l va inkor saqlanishi kerak.","hint":"wish were / wish had booked / wish would stop","audio":"/english-course/v7.23/en-b2-05-dictation.mp3","transcript":"If only I could hear the speaker."}]},"writing":{"task":"Shikoyat emailida muammo, afsus va so‘rovni aralashtirmasdan yozing.","audience":"Maktab kengashi yoki loyiha guruhi","minWords":90,"maxWords":320,"plan":["Da’vo va maqsadni aniqlang.","Reading va listeningdan bir dalilni qiyoslang.","Cheklov yoki qarshi fikrni tushuntiring.","Auditoriyaga mos amaliy xulosa yozing."],"model":"Dear manager, our club booked the room for a discussion, but loud music from the next room made it difficult to hear one another. I wish we had checked the programme before booking. However, we were not told that a noisy event would take place nearby. Thank you for offering a quieter room for the second half of our meeting. For future bookings, could you please provide information about other activities in the building? This would help groups choose a suitable space. We understand that different events have different needs, and we would appreciate a clear way to plan around them.","modelNotes":["Kirishda auditoriya va maqsad aniq.","Asosiy qism dalilni talqin bilan bog‘laydi.","Yakun haddan tashqari umumlashtirmaydi."],"phrases":["I wish the room were quieter.","I wish we had booked earlier.","I wish they would lower the music."],"checklist":["Topshiriq va auditoriyaga mos yozdim.","Fikrni o‘z so‘zlarim bilan ifodaladim.","Darsdagi shaklni to‘g‘ri ishlatdim.","Imlo, bog‘lanish va tinish belgilarini tekshirdim."]},"speaking":{"task":"Afsusni ayting, keyin hurmat bilan yordam so‘rang.","seconds":100,"prompts":["Reading va listening qayerda mos, qayerda farqli?","Sherigingizning e’tiroziga javob bering.","Qaysi dalil xulosangizni o‘zgartirishi mumkin?"],"rubric":["Vazifani bajarish","Til vositalari va aniqlik","Bog‘langan, tushunarli nutq","Talaffuz va muloqot"]},"rubrics":{"writing":["Mazmun va vazifani bajarish","Tuzilish va bog‘lanish","Til vositalari va uslub","Grammatika va imlo"],"speaking":["Vazifa va o‘zaro muloqot","Ravonlik va bog‘lanish","Til vositalari va aniqlik","Tushunarlilik va talaffuz"]},"realTask":"Shikoyat emailida muammo, afsus va so‘rovni aralashtirmasdan yozing.","exit":[[{"id":"en-b2-05-exit0","type":"grammarFill","skill":"grammar","prompt":"I wish we ___ checked earlier.","answers":["had"],"explanation":"Wish + past simple hozirgi boshqa holat istagi: I wish the room were quieter. Wish + had + V3 o‘tgan ishga afsus: I wish we had booked earlier. Wish + would boshqa odamning o‘zgarishi kutilgan xatti-harakatiga; oddiy o‘z qobiliyatingiz uchun could yoki past shakli.","hint":"wish were / wish had booked / wish would stop"},{"id":"en-b2-05-exit1","type":"grammarFill","skill":"grammar","prompt":"I wish they ___ lower the music.","answers":["would"],"explanation":"Wish + past simple hozirgi boshqa holat istagi: I wish the room were quieter. Wish + had + V3 o‘tgan ishga afsus: I wish we had booked earlier. Wish + would boshqa odamning o‘zgarishi kutilgan xatti-harakatiga; oddiy o‘z qobiliyatingiz uchun could yoki past shakli.","hint":"wish were / wish had booked / wish would stop"},{"id":"en-b2-05-exit2","type":"grammarFill","skill":"grammar","prompt":"If only I ___ hear the speaker.","answers":["could"],"explanation":"Wish + past simple hozirgi boshqa holat istagi: I wish the room were quieter. Wish + had + V3 o‘tgan ishga afsus: I wish we had booked earlier. Wish + would boshqa odamning o‘zgarishi kutilgan xatti-harakatiga; oddiy o‘z qobiliyatingiz uchun could yoki past shakli.","hint":"wish were / wish had booked / wish would stop"},{"id":"en-b2-05-exit3","type":"choice","skill":"grammar","prompt":"O‘tgan afsus qaysi?","answers":["I wish we had booked earlier."],"explanation":"Had booked o‘tmish.","hint":"wish were / wish had booked / wish would stop","options":["I wish we had booked earlier.","I wish it were quieter.","I wish they would stop."]},{"id":"en-b2-05-exit4","type":"choice","skill":"grammar","prompt":"Qaysi o‘tgan qaror afsus?","answers":["not checking the programme"],"explanation":"Had checked o‘tmish.","hint":"wish were / wish had booked / wish would stop","options":["not checking the programme","lowering the music","moving to a quiet room"]}],[{"id":"en-b2-05-exit-b0","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["I wish we had booked earlier."],"explanation":"Wish + past simple hozirgi boshqa holat istagi: I wish the room were quieter. Wish + had + V3 o‘tgan ishga afsus: I wish we had booked earlier. Wish + would boshqa odamning o‘zgarishi kutilgan xatti-harakatiga; oddiy o‘z qobiliyatingiz uchun could yoki past shakli.","hint":"wish were / wish had booked / wish would stop","tokens":["I","wish","we","had","booked","earlier."]},{"id":"en-b2-05-exit-b1","type":"grammarFill","skill":"grammar","prompt":"I wish they ___ lower the music.","answers":["would"],"explanation":"Wish + past simple hozirgi boshqa holat istagi: I wish the room were quieter. Wish + had + V3 o‘tgan ishga afsus: I wish we had booked earlier. Wish + would boshqa odamning o‘zgarishi kutilgan xatti-harakatiga; oddiy o‘z qobiliyatingiz uchun could yoki past shakli.","hint":"wish were / wish had booked / wish would stop"},{"id":"en-b2-05-exit-b2","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["If only I could hear the speaker."],"explanation":"Wish + past simple hozirgi boshqa holat istagi: I wish the room were quieter. Wish + had + V3 o‘tgan ishga afsus: I wish we had booked earlier. Wish + would boshqa odamning o‘zgarishi kutilgan xatti-harakatiga; oddiy o‘z qobiliyatingiz uchun could yoki past shakli.","hint":"wish were / wish had booked / wish would stop","tokens":["If","only","I","could","hear","the","speaker."]},{"id":"en-b2-05-exit-b3","type":"choice","skill":"grammar","prompt":"O‘tgan afsus qaysi?","answers":["I wish we had booked earlier."],"explanation":"Had booked o‘tmish.","hint":"wish were / wish had booked / wish would stop","options":["I wish we had booked earlier.","I wish it were quieter.","I wish they would stop."]},{"id":"en-b2-05-exit-b4","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["I wish I knew another place."],"explanation":"Wish + past simple hozirgi boshqa holat istagi: I wish the room were quieter. Wish + had + V3 o‘tgan ishga afsus: I wish we had booked earlier. Wish + would boshqa odamning o‘zgarishi kutilgan xatti-harakatiga; oddiy o‘z qobiliyatingiz uchun could yoki past shakli.","hint":"wish were / wish had booked / wish would stop","tokens":["I","wish","I","knew","another","place."]}]],"sources":[{"id":"cefr","name":"Council of Europe — CEFR daraja tavsiflari","levels":["PRE","A1","A2","B1","B2","C1"],"skill":"framework","url":"https://www.coe.int/en/web/common-european-framework-reference-languages/level-descriptions","task":"Dars maqsadini qila olaman tavsifi bilan solishtiring. PRE — kursning tayyorlov bosqichi.","lesson":"en-b2-05","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"pronunciation","name":"Cambridge Dictionary — Pronunciation","levels":["PRE","A1","A2","B1","B2","C1"],"skill":"pronunciation","url":"https://dictionary.cambridge.org/pronunciation/","task":"Darsdan ikki so‘z tanlang, UK/US talaffuzini eshiting va urg‘uni qayd eting.","lesson":"en-b2-05","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-grammar","name":"British Council — Grammar","levels":["A1","A2","B1","B2","C1"],"skill":"grammar","url":"https://learnenglish.britishcouncil.org/free-resources/grammar","task":"Darajangizdagi dars mavzusini toping va bitta o‘xshash misol yozing.","lesson":"en-b2-05","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-read","name":"British Council — Reading","levels":["A1","A2","B1","B2","C1"],"skill":"reading","url":"https://learnenglish.britishcouncil.org/free-resources/reading","task":"O‘z darajangizdagi matnni tanlang; asosiy fikr va bitta dalilni ajrating.","lesson":"en-b2-05","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-write","name":"British Council — Writing","levels":["A1","A2","B1","B2","C1"],"skill":"writing","url":"https://learnenglish.britishcouncil.org/free-resources/writing","task":"Darajangizdagi namunaning kirish, asosiy qism va yakunini tahlil qiling.","lesson":"en-b2-05","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-speak","name":"British Council — Speaking (A1–B2)","levels":["A1","A2","B1","B2"],"skill":"speaking","url":"https://learnenglish.britishcouncil.org/free-resources/speaking","task":"Darajangizdagi video vaziyatidan ikki iborani o‘z dialogingizda ishlating.","lesson":"en-b2-05","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-listen","name":"British Council — Listening (A1–C1)","levels":["A1","A2","B1","B2","C1"],"skill":"listening","url":"https://learnenglish.britishcouncil.org/free-resources/listening","task":"Mos daraja audiosini transkriptsiz tinglang; keyin yozuv bilan tekshiring.","lesson":"en-b2-05","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"cambridge","name":"Cambridge English — Activities","levels":["A1","A2","B1","B2","C1"],"skill":"integrated","url":"https://www.cambridgeenglish.org/learning-english/activities-for-learners/","task":"A1–A2, B1–B2 yoki C1–C2 filtrini qo‘llang; dars ko‘nikmasiga mos mashqni tanlang.","lesson":"en-b2-05","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."}],"recapEvery":4,"project":false,"rights":"Original SinfQuiz content; local Flite synthetic speech. Educational references are linked, not copied."}'::jsonb) on conflict(id,revision) do nothing;
insert into public.sq_en_content(id,base_id,owner_id,level,ordinal,status,revision,payload) values('en-b2-06','en-b2-06',null,4,6,'published',1,'{"id":"en-b2-06","baseId":"en-b2-06","revision":1,"level":"B2","levelIndex":4,"order":6,"title":"Would rather va had better","objective":"Afzallikni ogohlantirishdan ajratib, mos ohangda tavsiya berasiz.","context":"Taqdimot oldidagi ikki tanlov.","prerequisites":["en-b2-05"],"minutes":55,"skills":["grammar","vocabulary","pronunciation","listening","reading","writing","speaking"],"rules":["Would rather + V afzallik; boshqa ega bilan would rather + subject + past simple.","Had better + V vaziyatga bog‘liq kuchli maslahat; salbiy oqibat ehtimoli bor.","Had better not; would rather not. Had better o‘tgan zamon emas va would rather bilan bir xil kuchda emas."],"pattern":"would rather practise / would rather you checked / had better save","examples":["I would rather practise now.","I would rather you checked the slides.","We had better save a copy.","You had better not rely on one computer.","She would rather not speak first.","Would you rather work in pairs?"],"vocabulary":[{"id":"en-b2-06-v0","term":"backup","meaning":"zaxira nusxa","ipa":"/ˈbækʌp/","collocation":"keep a backup","example":"She says they had better save a backup because a technical problem could stop the talk."},{"id":"en-b2-06-v1","term":"preference","meaning":"afzallik","ipa":"/ˈprefərəns/","collocation":"express a preference","example":"Both activities are useful, and neither preference is a rule."},{"id":"en-b2-06-v2","term":"warning","meaning":"ogohlantirish","ipa":"/ˈwɔːnɪŋ/","collocation":"a practical warning","example":"Treating every preference as a warning would create unnecessary pressure."},{"id":"en-b2-06-v3","term":"rely on","meaning":"tayanmoq","ipa":"/rɪˈlaɪ ɒn/","collocation":"rely on one device","example":"You had better not rely on one computer."}],"visuals":[{"kind":"argument","title":"Ma’no va tuzilish","items":["would rather practise / would rather you checked / had better save","I would rather practise now.","I would rather you checked the slides."]},{"kind":"argument","title":"Fikr va dalilning aloqasi","items":["Two preferences serve the same aim.","One missing backup creates a serious risk.","Deal with the risk, then divide the tasks."]}],"pronunciation":{"focus":"Gapdagi mazmunli so‘zlarni urg‘u bilan ayting. Nuqtada to‘xtab, yozuvni qayta tinglang.","text":"You had better not rely on one computer.","audio":"/english-course/v7.23/en-b2-06-dictation.mp3"},"exercises":[{"id":"en-b2-06-choice","type":"choice","skill":"grammar","prompt":"Til vositasini tanlang: I would rather ___ now. (practise)","answers":["practise"],"explanation":"Would rather + V afzallik; boshqa ega bilan would rather + subject + past simple. Had better + V vaziyatga bog‘liq kuchli maslahat; salbiy oqibat ehtimoli bor. Had better not; would rather not. Had better o‘tgan zamon emas va would rather bilan bir xil kuchda emas.","hint":"would rather practise / would rather you checked / had better save","options":["practise","practising","practised"]},{"id":"en-b2-06-gap","type":"grammarFill","skill":"grammar","prompt":"I would rather ___ now. (practise)","answers":["practise"],"explanation":"Would rather + V afzallik; boshqa ega bilan would rather + subject + past simple. Had better + V vaziyatga bog‘liq kuchli maslahat; salbiy oqibat ehtimoli bor. Had better not; would rather not. Had better o‘tgan zamon emas va would rather bilan bir xil kuchda emas.","hint":"would rather practise / would rather you checked / had better save"},{"id":"en-b2-06-order","type":"order","skill":"grammar","prompt":"Kartalarni to‘g‘ri tartibga qo‘ying.","answers":["I would rather practise now."],"explanation":"Would rather + V afzallik; boshqa ega bilan would rather + subject + past simple. Had better + V vaziyatga bog‘liq kuchli maslahat; salbiy oqibat ehtimoli bor. Had better not; would rather not. Had better o‘tgan zamon emas va would rather bilan bir xil kuchda emas.","hint":"would rather practise / would rather you checked / had better save","tokens":["I","would","rather","practise","now."]},{"id":"en-b2-06-fix","type":"correction","skill":"grammar","prompt":"We had better to save a copy.","answers":["We had better save a copy."],"explanation":"Would rather + V afzallik; boshqa ega bilan would rather + subject + past simple. Had better + V vaziyatga bog‘liq kuchli maslahat; salbiy oqibat ehtimoli bor. Had better not; would rather not. Had better o‘tgan zamon emas va would rather bilan bir xil kuchda emas.","hint":"would rather practise / would rather you checked / had better save"},{"id":"en-b2-06-vocabulary","type":"matching","skill":"vocabulary","prompt":"So‘zlarni ma’nolari bilan moslang.","answers":["zaxira nusxa","afzallik","ogohlantirish","tayanmoq"],"explanation":"So‘zni alohida emas, darsdagi birikma va gap bilan eslang.","hint":"would rather practise / would rather you checked / had better save","left":["backup","preference","warning","rely on"],"options":["zaxira nusxa","afzallik","ogohlantirish","tayanmoq"]},{"id":"en-b2-06-transform","type":"transformation","skill":"grammar","prompt":"Boshqa ega bilan afzallik: Please check the slides; that is my preference.","answers":["I would rather you checked the slides."],"hint":"would rather practise / would rather you checked / had better save","explanation":"Would rather + V afzallik; boshqa ega bilan would rather + subject + past simple."},{"id":"en-b2-06-paragraphs","type":"paragraphOrder","skill":"reading","prompt":"Fikrni tartiblang: da’vo → dalil → talqin.","tokens":["Two preferences serve the same aim.","One missing backup creates a serious risk.","Deal with the risk, then divide the tasks."],"answers":["Two preferences serve the same aim.\nOne missing backup creates a serious risk.\nDeal with the risk, then divide the tasks."],"hint":"Da’vo nimani aytadi? Dalil nimani ko‘rsatadi?","explanation":"Dalil yakuniy xulosaning o‘rnini bosmaydi; talqin ularning aloqasini tushuntiradi."},{"id":"en-b2-06-collocations","type":"collocation","skill":"vocabulary","prompt":"So‘zlarni darsdagi birikmasi bilan moslang.","left":["backup","preference","warning","rely on"],"options":["keep a backup","express a preference","a practical warning","rely on one device"],"answers":["keep a backup","express a preference","a practical warning","rely on one device"],"hint":"So‘z qaysi birikmada ishlatilishini eslang.","explanation":"Birikmani yozgan gapingizda ham ishlating."}],"reading":{"title":"Asosiy matn va muallif pozitsiyasi","text":"Before the school presentation, two students discuss how to use the final twenty minutes. One would rather practise speaking; the other prefers checking the slides. Both activities are useful, and neither preference is a rule. A teacher then notices that the only copy of the presentation is on one computer. She says they had better save a backup because a technical problem could stop the talk. This advice has a stronger practical reason than either student’s preference. The group divides the time: one checks the slides while the other rehearses, and they save an extra copy first. The conversation works because they explain the purpose behind each suggestion. Treating every preference as a warning would create unnecessary pressure. Treating a real risk as a minor preference could leave the group unprepared.","sentences":["Before the school presentation, two students discuss how to use the final twenty minutes.","One would rather practise speaking; the other prefers checking the slides.","Both activities are useful, and neither preference is a rule.","A teacher then notices that the only copy of the presentation is on one computer.","She says they had better save a backup because a technical problem could stop the talk.","This advice has a stronger practical reason than either student’s preference.","The group divides the time: one checks the slides while the other rehearses, and they save an extra copy first.","The conversation works because they explain the purpose behind each suggestion.","Treating every preference as a warning would create unnecessary pressure.","Treating a real risk as a minor preference could leave the group unprepared."],"questions":[{"id":"en-b2-06-reading0","type":"choice","skill":"reading","prompt":"Nima kuchli maslahatga sabab?","answers":["only one copy could be lost"],"explanation":"Zaxirasiz texnik xavf.","hint":"would rather practise / would rather you checked / had better save","options":["only one copy could be lost","one student dislikes speaking","slides are always wrong"]},{"id":"en-b2-06-reading1","type":"choice","skill":"reading","prompt":"Rollar qanday bo‘lindi?","answers":["check and rehearse in parallel"],"explanation":"Ikkala foydali ish.","hint":"would rather practise / would rather you checked / had better save","options":["check and rehearse in parallel","do nothing","only discuss preferences"]},{"id":"en-b2-06-evidence","type":"evidence","skill":"reading","prompt":"Vaziyatni tanishtiradigan birinchi jumlani tanlang.","answers":["0"],"explanation":"Birinchi jumla matn vaziyatini tanishtiradi; keyingi jumlalar uni rivojlantiradi.","hint":"would rather practise / would rather you checked / had better save","options":["Before the school presentation, two students discuss how to use the final twenty minutes.","One would rather practise speaking; the other prefers checking the slides.","Both activities are useful, and neither preference is a rule.","A teacher then notices that the only copy of the presentation is on one computer.","She says they had better save a backup because a technical problem could stop the talk.","This advice has a stronger practical reason than either student’s preference.","The group divides the time: one checks the slides while the other rehearses, and they save an extra copy first.","The conversation works because they explain the purpose behind each suggestion.","Treating every preference as a warning would create unnecessary pressure.","Treating a real risk as a minor preference could leave the group unprepared."]}]},"listening":{"title":"Boshqa nuqtayi nazarni tinglang","transcript":"I would rather practise the talk now. Could you check the slides? Before we do either task, we had better save a backup. There is only one copy, and we should not rely on one computer.","audio":"/english-course/v7.23/en-b2-06.mp3","synthetic":true,"questions":[{"id":"en-b2-06-listening0","type":"choice","skill":"listening","prompt":"Avval nima?","answers":["save a backup"],"explanation":"Before either task backup.","hint":"would rather practise / would rather you checked / had better save","options":["save a backup","cancel the talk","buy a computer"]},{"id":"en-b2-06-listening1","type":"choice","skill":"listening","prompt":"Kim slaydni tekshirsin?","answers":["the listener"],"explanation":"Could you.","hint":"would rather practise / would rather you checked / had better save","options":["the listener","the entire audience","nobody"]},{"id":"en-b2-06-audio-table","type":"table","skill":"listening","prompt":"Tinglangan ma’lumotni jadvalga yozing.","answers":["backup","practise the talk"],"explanation":"Jadvaldagi javoblar yozuvda aynan aytilgan. Mavjud bo‘lmagan tafsilotni taxmin qilmang.","hint":"would rather practise / would rather you checked / had better save","rows":["Birinchi xavf yechimi","Afzallik"]},{"id":"en-b2-06-dictation","type":"dictation","skill":"listening","prompt":"Eshitgan gapingizni yozing.","answers":["You had better not rely on one computer."],"explanation":"Gapdagi asosiy so‘zlar, yordamchi fe’l va inkor saqlanishi kerak.","hint":"would rather practise / would rather you checked / had better save","audio":"/english-course/v7.23/en-b2-06-dictation.mp3","transcript":"You had better not rely on one computer."}]},"writing":{"task":"Ikki afzallik va bitta zarur ogohlantirish bilan hamkorlik rejasini yozing.","audience":"Maktab kengashi yoki loyiha guruhi","minWords":90,"maxWords":320,"plan":["Da’vo va maqsadni aniqlang.","Reading va listeningdan bir dalilni qiyoslang.","Cheklov yoki qarshi fikrni tushuntiring.","Auditoriyaga mos amaliy xulosa yozing."],"model":"We have twenty minutes before the presentation. I would rather practise the explanation, while my partner would prefer to check the slides. Both tasks support the same aim, so we can work in parallel instead of arguing about which one is more useful. First, we had better save a backup because the presentation is currently stored on only one computer. If that device fails, our preferences will no longer matter. Once the copy is safe, we can use ten minutes for preparation and ten for a joint rehearsal. This plan respects individual preferences while dealing with the most important risk first.","modelNotes":["Kirishda auditoriya va maqsad aniq.","Asosiy qism dalilni talqin bilan bog‘laydi.","Yakun haddan tashqari umumlashtirmaydi."],"phrases":["I would rather practise now.","I would rather you checked the slides.","We had better save a copy."],"checklist":["Topshiriq va auditoriyaga mos yozdim.","Fikrni o‘z so‘zlarim bilan ifodaladim.","Darsdagi shaklni to‘g‘ri ishlatdim.","Imlo, bog‘lanish va tinish belgilarini tekshirdim."]},"speaking":{"task":"Sherik bilan ikki variantdan birini kelishib tanlang; maslahat kuchini asoslang.","seconds":100,"prompts":["Reading va listening qayerda mos, qayerda farqli?","Sherigingizning e’tiroziga javob bering.","Qaysi dalil xulosangizni o‘zgartirishi mumkin?"],"rubric":["Vazifani bajarish","Til vositalari va aniqlik","Bog‘langan, tushunarli nutq","Talaffuz va muloqot"]},"rubrics":{"writing":["Mazmun va vazifani bajarish","Tuzilish va bog‘lanish","Til vositalari va uslub","Grammatika va imlo"],"speaking":["Vazifa va o‘zaro muloqot","Ravonlik va bog‘lanish","Til vositalari va aniqlik","Tushunarlilik va talaffuz"]},"realTask":"Ikki afzallik va bitta zarur ogohlantirish bilan hamkorlik rejasini yozing.","exit":[[{"id":"en-b2-06-exit0","type":"grammarFill","skill":"grammar","prompt":"I would rather ___ now. (practise)","answers":["practise"],"explanation":"Would rather + V afzallik; boshqa ega bilan would rather + subject + past simple. Had better + V vaziyatga bog‘liq kuchli maslahat; salbiy oqibat ehtimoli bor. Had better not; would rather not. Had better o‘tgan zamon emas va would rather bilan bir xil kuchda emas.","hint":"would rather practise / would rather you checked / had better save"},{"id":"en-b2-06-exit1","type":"grammarFill","skill":"grammar","prompt":"I would rather you ___ the slides. (check)","answers":["checked"],"explanation":"Would rather + V afzallik; boshqa ega bilan would rather + subject + past simple. Had better + V vaziyatga bog‘liq kuchli maslahat; salbiy oqibat ehtimoli bor. Had better not; would rather not. Had better o‘tgan zamon emas va would rather bilan bir xil kuchda emas.","hint":"would rather practise / would rather you checked / had better save"},{"id":"en-b2-06-exit2","type":"grammarFill","skill":"grammar","prompt":"We had better not ___ on one device. (rely)","answers":["rely"],"explanation":"Would rather + V afzallik; boshqa ega bilan would rather + subject + past simple. Had better + V vaziyatga bog‘liq kuchli maslahat; salbiy oqibat ehtimoli bor. Had better not; would rather not. Had better o‘tgan zamon emas va would rather bilan bir xil kuchda emas.","hint":"would rather practise / would rather you checked / had better save"},{"id":"en-b2-06-exit3","type":"choice","skill":"grammar","prompt":"Kuchli vaziyatli maslahat?","answers":["You had better save a backup."],"explanation":"Risk sababli had better.","hint":"would rather practise / would rather you checked / had better save","options":["You had better save a backup.","I would rather sit here.","I prefer blue."]},{"id":"en-b2-06-exit4","type":"choice","skill":"grammar","prompt":"Rollar qanday bo‘lindi?","answers":["check and rehearse in parallel"],"explanation":"Ikkala foydali ish.","hint":"would rather practise / would rather you checked / had better save","options":["check and rehearse in parallel","do nothing","only discuss preferences"]}],[{"id":"en-b2-06-exit-b0","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["I would rather you checked the slides."],"explanation":"Would rather + V afzallik; boshqa ega bilan would rather + subject + past simple. Had better + V vaziyatga bog‘liq kuchli maslahat; salbiy oqibat ehtimoli bor. Had better not; would rather not. Had better o‘tgan zamon emas va would rather bilan bir xil kuchda emas.","hint":"would rather practise / would rather you checked / had better save","tokens":["I","would","rather","you","checked","the","slides."]},{"id":"en-b2-06-exit-b1","type":"grammarFill","skill":"grammar","prompt":"I would rather you ___ the slides. (check)","answers":["checked"],"explanation":"Would rather + V afzallik; boshqa ega bilan would rather + subject + past simple. Had better + V vaziyatga bog‘liq kuchli maslahat; salbiy oqibat ehtimoli bor. Had better not; would rather not. Had better o‘tgan zamon emas va would rather bilan bir xil kuchda emas.","hint":"would rather practise / would rather you checked / had better save"},{"id":"en-b2-06-exit-b2","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["You had better not rely on one computer."],"explanation":"Would rather + V afzallik; boshqa ega bilan would rather + subject + past simple. Had better + V vaziyatga bog‘liq kuchli maslahat; salbiy oqibat ehtimoli bor. Had better not; would rather not. Had better o‘tgan zamon emas va would rather bilan bir xil kuchda emas.","hint":"would rather practise / would rather you checked / had better save","tokens":["You","had","better","not","rely","on","one","computer."]},{"id":"en-b2-06-exit-b3","type":"choice","skill":"grammar","prompt":"Kuchli vaziyatli maslahat?","answers":["You had better save a backup."],"explanation":"Risk sababli had better.","hint":"would rather practise / would rather you checked / had better save","options":["You had better save a backup.","I would rather sit here.","I prefer blue."]},{"id":"en-b2-06-exit-b4","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["Would you rather work in pairs?"],"explanation":"Would rather + V afzallik; boshqa ega bilan would rather + subject + past simple. Had better + V vaziyatga bog‘liq kuchli maslahat; salbiy oqibat ehtimoli bor. Had better not; would rather not. Had better o‘tgan zamon emas va would rather bilan bir xil kuchda emas.","hint":"would rather practise / would rather you checked / had better save","tokens":["Would","you","rather","work","in","pairs?"]}]],"sources":[{"id":"cefr","name":"Council of Europe — CEFR daraja tavsiflari","levels":["PRE","A1","A2","B1","B2","C1"],"skill":"framework","url":"https://www.coe.int/en/web/common-european-framework-reference-languages/level-descriptions","task":"Dars maqsadini qila olaman tavsifi bilan solishtiring. PRE — kursning tayyorlov bosqichi.","lesson":"en-b2-06","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"pronunciation","name":"Cambridge Dictionary — Pronunciation","levels":["PRE","A1","A2","B1","B2","C1"],"skill":"pronunciation","url":"https://dictionary.cambridge.org/pronunciation/","task":"Darsdan ikki so‘z tanlang, UK/US talaffuzini eshiting va urg‘uni qayd eting.","lesson":"en-b2-06","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-grammar","name":"British Council — Grammar","levels":["A1","A2","B1","B2","C1"],"skill":"grammar","url":"https://learnenglish.britishcouncil.org/free-resources/grammar","task":"Darajangizdagi dars mavzusini toping va bitta o‘xshash misol yozing.","lesson":"en-b2-06","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-read","name":"British Council — Reading","levels":["A1","A2","B1","B2","C1"],"skill":"reading","url":"https://learnenglish.britishcouncil.org/free-resources/reading","task":"O‘z darajangizdagi matnni tanlang; asosiy fikr va bitta dalilni ajrating.","lesson":"en-b2-06","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-write","name":"British Council — Writing","levels":["A1","A2","B1","B2","C1"],"skill":"writing","url":"https://learnenglish.britishcouncil.org/free-resources/writing","task":"Darajangizdagi namunaning kirish, asosiy qism va yakunini tahlil qiling.","lesson":"en-b2-06","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-speak","name":"British Council — Speaking (A1–B2)","levels":["A1","A2","B1","B2"],"skill":"speaking","url":"https://learnenglish.britishcouncil.org/free-resources/speaking","task":"Darajangizdagi video vaziyatidan ikki iborani o‘z dialogingizda ishlating.","lesson":"en-b2-06","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-listen","name":"British Council — Listening (A1–C1)","levels":["A1","A2","B1","B2","C1"],"skill":"listening","url":"https://learnenglish.britishcouncil.org/free-resources/listening","task":"Mos daraja audiosini transkriptsiz tinglang; keyin yozuv bilan tekshiring.","lesson":"en-b2-06","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"cambridge","name":"Cambridge English — Activities","levels":["A1","A2","B1","B2","C1"],"skill":"integrated","url":"https://www.cambridgeenglish.org/learning-english/activities-for-learners/","task":"A1–A2, B1–B2 yoki C1–C2 filtrini qo‘llang; dars ko‘nikmasiga mos mashqni tanlang.","lesson":"en-b2-06","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘