insert into public.sq_en_content(id,base_id,owner_id,level,ordinal,status,revision,payload) values('en-b2-07','en-b2-07',null,4,7,'published',1,'{"id":"en-b2-07","baseId":"en-b2-07","revision":1,"level":"B2","levelIndex":4,"order":7,"title":"Past modals: dalil, ehtimol va tanqid","objective":"Must have, might have va should have bilan turli ishonchni ko‘rsatasiz.","context":"Past modals: dalil, ehtimol va tanqid","prerequisites":["en-b2-06"],"minutes":55,"skills":["grammar","vocabulary","pronunciation","listening","reading","writing","speaking"],"rules":["Must have + V3 kuchli xulosa, might have ehtimol.","Can’t have dalilga zid natijani rad etadi; should have o‘tgan maslahat yoki tanqid.","Didn’t need to bilan needn’t have done bir xil emas: ikkinchisida ish bajarilgan."],"pattern":"must have / might have / should have + V3","examples":["She must have left early.","They might have taken another bus.","He cannot have read the final version.","We should have checked the address.","You need not have printed two copies.","The message may have gone to spam."],"vocabulary":[{"id":"en-b2-07-v0","term":"assumption","meaning":"taxmin","ipa":"/əˈsʌmpʃən/","collocation":"question an assumption","example":"question an assumption"},{"id":"en-b2-07-v1","term":"plausible","meaning":"ishonarli","ipa":"/ˈplɔːzəbəl/","collocation":"a plausible explanation","example":"a plausible explanation"},{"id":"en-b2-07-v2","term":"verify","meaning":"tekshirmoq","ipa":"/ˈverɪfaɪ/","collocation":"verify an address","example":"verify an address"},{"id":"en-b2-07-v3","term":"oversight","meaning":"e’tiborsizlik","ipa":"/ˈəʊvəsaɪt/","collocation":"a small oversight","example":"a small oversight"}],"visuals":[{"kind":"argument","title":"Ma’no va tuzilish","items":["must have / might have / should have + V3","She must have left early.","They might have taken another bus."]},{"kind":"argument","title":"Fikr va dalilning aloqasi","items":["The cause was initially uncertain.","The invitation contained an old address.","Verify details before drawing conclusions."]}],"pronunciation":{"focus":"Gapdagi mazmunli so‘zlarni urg‘u bilan ayting. Nuqtada to‘xtab, yozuvni qayta tinglang.","text":"We should have checked the address.","audio":"/english-course/v7.23/en-b2-07-dictation.mp3"},"exercises":[{"id":"en-b2-07-choice","type":"choice","skill":"grammar","prompt":"Til vositasini tanlang: She might have ___ another bus. (take)","answers":["taken"],"explanation":"Must have + V3 kuchli xulosa, might have ehtimol. Can’t have dalilga zid natijani rad etadi; should have o‘tgan maslahat yoki tanqid. Didn’t need to bilan needn’t have done bir xil emas: ikkinchisida ish bajarilgan.","hint":"must have / might have / should have + V3","options":["taken","take","taking"]},{"id":"en-b2-07-gap","type":"grammarFill","skill":"grammar","prompt":"She might have ___ another bus. (take)","answers":["taken"],"explanation":"Must have + V3 kuchli xulosa, might have ehtimol. Can’t have dalilga zid natijani rad etadi; should have o‘tgan maslahat yoki tanqid. Didn’t need to bilan needn’t have done bir xil emas: ikkinchisida ish bajarilgan.","hint":"must have / might have / should have + V3"},{"id":"en-b2-07-order","type":"order","skill":"grammar","prompt":"Kartalarni to‘g‘ri tartibga qo‘ying.","answers":["She must have left early."],"explanation":"Must have + V3 kuchli xulosa, might have ehtimol. Can’t have dalilga zid natijani rad etadi; should have o‘tgan maslahat yoki tanqid. Didn’t need to bilan needn’t have done bir xil emas: ikkinchisida ish bajarilgan.","hint":"must have / might have / should have + V3","tokens":["She","must","have","left","early."]},{"id":"en-b2-07-fix","type":"correction","skill":"grammar","prompt":"She must has forgotten.","answers":["She must have forgotten."],"explanation":"Must have + V3 kuchli xulosa, might have ehtimol. Can’t have dalilga zid natijani rad etadi; should have o‘tgan maslahat yoki tanqid. Didn’t need to bilan needn’t have done bir xil emas: ikkinchisida ish bajarilgan.","hint":"must have / might have / should have + V3"},{"id":"en-b2-07-vocabulary","type":"matching","skill":"vocabulary","prompt":"So‘zlarni ma’nolari bilan moslang.","answers":["taxmin","ishonarli","tekshirmoq","e’tiborsizlik"],"explanation":"So‘zni alohida emas, darsdagi birikma va gap bilan eslang.","hint":"must have / might have / should have + V3","left":["assumption","plausible","verify","oversight"],"options":["taxmin","ishonarli","tekshirmoq","e’tiborsizlik"]},{"id":"en-b2-07-transform","type":"transformation","skill":"grammar","prompt":"Ehtimol sifatida: Perhaps she took another bus.","answers":["She might have taken another bus."],"hint":"must have / might have / should have + V3","explanation":"Must have + V3 kuchli xulosa, might have ehtimol."},{"id":"en-b2-07-paragraphs","type":"paragraphOrder","skill":"reading","prompt":"Fikrni tartiblang: da’vo → dalil → talqin.","tokens":["The cause was initially uncertain.","The invitation contained an old address.","Verify details before drawing conclusions."],"answers":["The cause was initially uncertain.\nThe invitation contained an old address.\nVerify details before drawing conclusions."],"hint":"Da’vo nimani aytadi? Dalil nimani ko‘rsatadi?","explanation":"Dalil yakuniy xulosaning o‘rnini bosmaydi; talqin ularning aloqasini tushuntiradi."}],"reading":{"title":"Asosiy matn va muallif pozitsiyasi","text":"The speaker has not arrived, although the meeting began ten minutes ago. One student says she must have forgotten. Another suggests that she might have taken the wrong bus. Neither has spoken to her, so the first explanation is stronger than the evidence allows. The organiser checks the invitation and finds an old address. They should have verified it before sending. The speaker then calls from the other building. This confirms one explanation but does not justify blaming her for forgetting. Reviewing the language matters: a possibility should not become a fact just because it is repeated confidently. The next invitation will include a map and a contact number.","sentences":["The speaker has not arrived, although the meeting began ten minutes ago.","One student says she must have forgotten.","Another suggests that she might have taken the wrong bus.","Neither has spoken to her, so the first explanation is stronger than the evidence allows.","The organiser checks the invitation and finds an old address.","They should have verified it before sending.","The speaker then calls from the other building.","This confirms one explanation but does not justify blaming her for forgetting.","Reviewing the language matters: a possibility should not become a fact just because it is repeated confidently.","The next invitation will include a map and a contact number."],"questions":[{"id":"en-b2-07-reading0","type":"choice","skill":"reading","prompt":"Avvalgi qat’iy xulosa muammosi?","answers":["it exceeded the evidence"],"explanation":"Dalilsiz must have juda qat’iy.","hint":"must have / might have / should have + V3","options":["it exceeded the evidence","it was confirmed immediately","it had no grammar"]},{"id":"en-b2-07-reading1","type":"choice","skill":"reading","prompt":"Old address nimani tushuntiradi?","answers":["why she went elsewhere"],"explanation":"Keyingi telefon xabari joyni tasdiqlaydi.","hint":"must have / might have / should have + V3","options":["why she went elsewhere","why she dislikes meetings","why buses stopped"]},{"id":"en-b2-07-evidence","type":"evidence","skill":"reading","prompt":"Vaziyatni tanishtiradigan birinchi jumlani tanlang.","answers":["0"],"explanation":"Birinchi jumla matn vaziyatini tanishtiradi; keyingi jumlalar uni rivojlantiradi.","hint":"must have / might have / should have + V3","options":["The speaker has not arrived, although the meeting began ten minutes ago.","One student says she must have forgotten.","Another suggests that she might have taken the wrong bus.","Neither has spoken to her, so the first explanation is stronger than the evidence allows.","The organiser checks the invitation and finds an old address.","They should have verified it before sending.","The speaker then calls from the other building.","This confirms one explanation but does not justify blaming her for forgetting.","Reviewing the language matters: a possibility should not become a fact just because it is repeated confidently.","The next invitation will include a map and a contact number."]}]},"listening":{"title":"Boshqa nuqtayi nazarni tinglang","transcript":"Speaker one: Our key word is address. The speaker has not arrived, although the meeting began ten minutes ago. One student says she must have forgotten. Speaker two: My main point is verification. We should verify information before blaming someone. The speaker has not arrived, although the meeting began ten minutes ago. One student says she must have forgotten. Another suggests that she might have taken the wrong bus. Neither has spoken to her, so the first explanation is stronger than the evidence allows. The organiser checks the invitation and finds an old address. They should have verified it before sending. The speaker then calls from the other building. This confirms one explanation but does not justify blaming her for forgetting. Reviewing the language matters: a possibility should not become a fact just because it is repeated confidently. The next invitation will include a map and a contact number.","audio":"/english-course/v7.23/en-b2-07.mp3","synthetic":true,"questions":[{"id":"en-b2-07-listening0","type":"choice","skill":"listening","prompt":"Avvalgi qat’iy xulosa muammosi?","answers":["it exceeded the evidence"],"explanation":"Dalilsiz must have juda qat’iy.","hint":"must have / might have / should have + V3","options":["it exceeded the evidence","it was confirmed immediately","it had no grammar"]},{"id":"en-b2-07-listening1","type":"choice","skill":"listening","prompt":"Old address nimani tushuntiradi?","answers":["why she went elsewhere"],"explanation":"Keyingi telefon xabari joyni tasdiqlaydi.","hint":"must have / might have / should have + V3","options":["why she went elsewhere","why she dislikes meetings","why buses stopped"]},{"id":"en-b2-07-audio-table","type":"table","skill":"listening","prompt":"Tinglangan ma’lumotni jadvalga yozing.","answers":["address","verification"],"explanation":"Jadvaldagi javoblar yozuvda aynan aytilgan. Mavjud bo‘lmagan tafsilotni taxmin qilmang.","hint":"must have / might have / should have + V3","rows":["Birinchi gapdagi asosiy so‘z","Sherikning asosiy fikri"]},{"id":"en-b2-07-dictation","type":"dictation","skill":"listening","prompt":"Eshitgan gapingizni yozing.","answers":["We should have checked the address."],"explanation":"Gapdagi asosiy so‘zlar, yordamchi fe’l va inkor saqlanishi kerak.","hint":"must have / might have / should have + V3","audio":"/english-course/v7.23/en-b2-07-dictation.mp3","transcript":"We should have checked the address."}]},"writing":{"task":"Kechikish haqidagi emailda fakt, ehtimol va yaxshilash tavsiyasini ajrating.","audience":"Maktab kengashi yoki loyiha guruhi","minWords":70,"maxWords":320,"plan":["Da’vo va maqsadni aniqlang.","Reading va listeningdan bir dalilni qiyoslang.","Cheklov yoki qarshi fikrni tushuntiring.","Auditoriyaga mos amaliy xulosa yozing."],"model":"We know that the speaker arrived at the old building. Before her call, we only had possible explanations for the delay. She might have taken the wrong bus, but there was no evidence that she had forgotten the meeting. We should have checked the invitation address before sending it. For the next event, please verify the location and include a contact number. This will reduce confusion and help us respond without blaming someone on the basis of an assumption.","modelNotes":["Kirishda auditoriya va maqsad aniq.","Asosiy qism dalilni talqin bilan bog‘laydi.","Yakun haddan tashqari umumlashtirmaydi."],"phrases":["She must have left early.","They might have taken another bus.","He cannot have read the final version."],"checklist":["Topshiriq va auditoriyaga mos yozdim.","Fikrni o‘z so‘zlarim bilan ifodaladim.","Darsdagi shaklni to‘g‘ri ishlatdim.","Imlo, bog‘lanish va tinish belgilarini tekshirdim."]},"speaking":{"task":"Reading va listeningni taqqoslang. Kechikish haqidagi emailda fakt, ehtimol va yaxshilash tavsiyasini ajrating. Sherigingizning e’tiroziga javob bering.","seconds":100,"prompts":["Reading va listening qayerda mos, qayerda farqli?","Sherigingizning e’tiroziga javob bering.","Qaysi dalil xulosangizni o‘zgartirishi mumkin?"],"rubric":["Vazifani bajarish","Til vositalari va aniqlik","Bog‘langan, tushunarli nutq","Talaffuz va muloqot"]},"rubrics":{"writing":["Mazmun va vazifani bajarish","Tuzilish va bog‘lanish","Til vositalari va uslub","Grammatika va imlo"],"speaking":["Vazifa va o‘zaro muloqot","Ravonlik va bog‘lanish","Til vositalari va aniqlik","Tushunarlilik va talaffuz"]},"realTask":"Kechikish haqidagi emailda fakt, ehtimol va yaxshilash tavsiyasini ajrating.","exit":[[{"id":"en-b2-07-exit0","type":"grammarFill","skill":"grammar","prompt":"She might have ___ another bus. (take)","answers":["taken"],"explanation":"Must have + V3 kuchli xulosa, might have ehtimol. Can’t have dalilga zid natijani rad etadi; should have o‘tgan maslahat yoki tanqid. Didn’t need to bilan needn’t have done bir xil emas: ikkinchisida ish bajarilgan.","hint":"must have / might have / should have + V3"},{"id":"en-b2-07-exit1","type":"grammarFill","skill":"grammar","prompt":"We should have ___ the address. (check)","answers":["checked"],"explanation":"Must have + V3 kuchli xulosa, might have ehtimol. Can’t have dalilga zid natijani rad etadi; should have o‘tgan maslahat yoki tanqid. Didn’t need to bilan needn’t have done bir xil emas: ikkinchisida ish bajarilgan.","hint":"must have / might have / should have + V3"},{"id":"en-b2-07-exit2","type":"grammarFill","skill":"grammar","prompt":"He cannot ___ read the new version.","answers":["have"],"explanatio